import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/selfhosted-photo-backup.db"
);

// Define row interfaces
export interface MediaRow {
  id: number;
  filename: string;
  filepath: string;
  size: number;
  created_at: string;
  updated_at: string;
  faces: string | null;
  albums: string | null;
  sharing: string | null;
}

// Create tables if they don't exist
const createMediaTable = `
  CREATE TABLE IF NOT EXISTS media (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    filename TEXT NOT NULL,
    filepath TEXT NOT NULL,
    size INTEGER NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    faces TEXT,
    albums TEXT,
    sharing TEXT
  )
`;

db.exec(createMediaTable);

// Query functions
export function getAllMedia(): MediaRow[] {
  const stmt = db.prepare(`SELECT * FROM media`);
  return stmt.all() as unknown as MediaRow[];
}

export function getMediaById(id: number): MediaRow | undefined {
  const stmt = db.prepare(`SELECT * FROM media WHERE id = ?`);
  return stmt.get(id) as unknown as MediaRow | undefined;
}

export function insertMedia(
  filename: string,
  filepath: string,
  size: number,
  created_at: string,
  updated_at: string,
  faces: string | null,
  albums: string | null,
  sharing: string | null
): number {
  const stmt = db.prepare(
    `INSERT INTO media (filename, filepath, size, created_at, updated_at, faces, albums, sharing) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
  );
  const result = stmt.run(filename, filepath, size, created_at, updated_at, faces, albums, sharing);
  return Number(result.lastInsertRowid);
}

export function updateMedia(
  id: number,
  filename: string,
  filepath: string,
  size: number,
  updated_at: string,
  faces: string | null,
  albums: string | null,
  sharing: string | null
): void {
  const stmt = db.prepare(
    `UPDATE media SET filename = ?, filepath = ?, size = ?, updated_at = ?, faces = ?, albums = ?, sharing = ? WHERE id = ?`
  );
  stmt.run(filename, filepath, size, updated_at, faces, albums, sharing, id);
}

export function deleteMedia(id: number): void {
  const stmt = db.prepare(`DELETE FROM media WHERE id = ?`);
  stmt.run(id);
}

// Seed data
if (getAllMedia().length === 0) {
  const now = new Date().toISOString();
  insertMedia(
    "vacation1.jpg",
