import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply to GET requests to album routes
  if (req.method !== "GET" || !req.path.startsWith("/album/")) {
    next();
    return;
  }

  const shareToken = req.headers["x-share-token"] as string | undefined;

  if (!shareToken) {
    res.status(401).json({ error: "Share token required" });
    return;
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Basic token format validation
  const parts = shareToken.split(".");
  if (parts.length !== 2) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  const [tokenPayload, tokenSignature] = parts;

  // Verify signature
  const expectedSignature = createHmac("sha256", secret)
    .update(tokenPayload)
    .digest("hex");

  const expectedBuffer = Buffer.from(expectedSignature);
  const actualBuffer = Buffer.from(tokenSignature);

  if (actualBuffer.length !== expectedBuffer.length || 
      !timingSafeEqual(actualBuffer, expectedBuffer)) {
    res.status(401).json({ error: "Invalid token signature" });
    return;
  }

  // Token is valid, proceed
  next();
}

import { useEffect, useState } from "react";

interface MediaItem {
  id: string;
  title: string;
  type: 'photo' | 'video';
  url: string;
  albumId?: string;
  tags: string[];
  folder: string;
}

interface Album {
  id: string;
  name: string;
}

export function PhotoGallery() {
  const [mediaItems, setMediaItems] = useState<MediaItem[]>([]);
  const [albums, setAlbums] = useState<Album[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchMedia();
    fetchAlbums();
  }, []);

  const fetchMedia = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/media-processing-service/media');
      if (!response.ok) {
        throw new Error(`Failed to fetch media: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setMediaItems(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const fetchAlbums = async () => {
    try {
      const response = await fetch('/api/media-processing-service/media');
      if (!response.ok) {
        throw new Error(`Failed to fetch albums: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      // Assuming the API returns album data in a specific format
      setAlbums(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/media-processing-service/media/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error(`Failed to delete media: ${response.status} ${response.statusText}`);
      }
      // Refresh the list after deletion
      fetchMedia();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Photo Gallery</h1>

      {mediaItems.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No media items found.</p>
      ) : (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
          {mediaItems.map(item => (
            <div key={item.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '10px', width: '200px' }}>
              <img 
                src={item.url} 
                alt={item.title} 
                style={{ width: '100%', height: 'auto', borderRadius: '4px' }} 
              />
              <h3 style={{ fontSize: '16px', margin: '10px 0 5px 0' }}>{item.title}</h3>
              <p style={{ fontSize: '14px', color: '#666' }}>{item.type}</p>
              <p style={{ fontSize: '14px', color: '#666' }}>{item.folder}</p>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '10px' }}>
                <button 
                  onClick={() => handleDelete(item.id)}
                  style={{ backgroundColor: '#ff4d4d', color: 'white', border: 'none', borderRadius: '4px', padding: '5px 10px' }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

