import { db, getAllMedia, getMediaById, insertMedia, updateMedia, deleteMedia } from "../db/media-table";
import { middleware as oauthMiddleware } from "../middleware/oauth-login";
import { middleware as readOnlyMiddleware } from "../middleware/read-only-share-mode";

export const router = Router();

// Get all media
router.get("/", oauthMiddleware, readOnlyMiddleware, (req: Request, res: Response) => {
  try {
    const media = getAllMedia();
    res.json(media);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch media" });
  }
});

// Get media by ID
router.get("/:id", oauthMiddleware, readOnlyMiddleware, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid media ID" });
    }

    const media = getMediaById(id);
    if (!media) {
      return res.status(404).json({ error: "Media not found" });
    }

    res.json(media);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch media" });
  }
});

// Create new media
router.post("/", oauthMiddleware, (req: Request, res: Response) => {
  try {
    const { filename, filepath, size, created_at, updated_at, faces, albums, sharing } = req.body;

    if (!filename || !filepath || !size || !created_at || !updated_at) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const newMedia = insertMedia(
      filename,
      filepath,
      size,
      created_at,
      updated_at,
      faces || null,
      albums || null,
      sharing || null
    );

    res.status(201).json(newMedia);
  } catch (error) {
    res.status(500).json({ error: "Failed to create media" });
  }
});

// Update media
router.put("/:id", oauthMiddleware, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid media ID" });
    }

    const { filename, filepath, size, updated_at, faces, albums, sharing } = req.body;

    if (!filename || !filepath || !size || !updated_at) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const updatedMedia = updateMedia(
      id,
      filename,
      filepath,
      size,
      updated_at,
      faces || null,
      albums || null,
      sharing || null
    );

    // Note: updateMedia returns void, so we can't test if it succeeded
    // We'll assume it worked since there's no error thrown
    res.json({ message: "Media updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update media" });
  }
});

// Delete media
router.delete("/:id", oauthMiddleware, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid media ID" });
    }

    const existingMedia = getMediaById(id);
    if (!existingMedia) {
      return res.status(404).json({ error: "Media not found" });
    }

    deleteMedia(id);
    res.json({ message: "Media deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete media" });
  }
});

