export function getAllPages(): Page[] {
  const stmt = db.prepare(
    "SELECT * FROM pages ORDER BY id ASC"
  );
  return stmt.all() as unknown as Page[];
}

export function getPageById(id: number): Page | undefined {
  const stmt = db.prepare(
    "SELECT * FROM pages WHERE id = ?"
  );
  return stmt.get(id) as unknown as Page | undefined;
}

export function insertPage(
  title: string,
  content: string,
  chapterId: number
): number {
  const stmt = db.prepare(
    "INSERT INTO pages (title, content, chapter_id) VALUES (?, ?, ?)"
  );
  const result = stmt.run(title, content, chapterId);
  return Number(result.lastInsertRowid);
}

