  id: number,
  title: string,
  content: string,
  chapterId: number
): void {
  const stmt = db.prepare(
    "UPDATE pages SET title = ?, content = ?, chapter_id = ? WHERE id = ?"
  );
  stmt.run(title, content, chapterId, id);
}

export function deletePage(id: number): void {
  const stmt = db.prepare("DELETE FROM pages WHERE id = ?");
  stmt.run(id);
}

