}

export function insertAccount(
  domain: string,
  account: string,
  alias: string | null,
  quota: number
): number {
  const stmt = db.prepare(
    "INSERT INTO mail_accounts (domain, account, alias, quota) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(domain, account, alias, quota);
  return Number(result.lastInsertRowid);
}

export function updateAccount(
  id: number,
  domain: string,
  account: string,
  alias: string | null,
  quota: number
): void {
  const stmt = db.prepare(
    "UPDATE mail_accounts SET domain = ?, account = ?, alias = ?, quota = ? WHERE id = ?"
  );
  stmt.run(domain, account, alias, quota, id);
}

