    res.json({ message: "Account deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete account" });
  }
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only enforce TLS for mail transport routes
  // Assuming mail transport happens on specific paths like /mail, /smtp, etc.
  const mailTransportPaths = ["/mail", "/smtp"];

  // Check if this is a mail transport request
  if (!mailTransportPaths.some(path => req.path.startsWith(path))) {
    next();
    return;
  }

  // Check if request is over HTTPS
  if (req.secure || req.header("X-Forwarded-Proto") === "https") {
    next();
    return;
  }

  // For non-HTTPS requests, check for DANE or MTA-STS headers
  const daneHeader = req.header("DANE-TLSA");
  const mtastsHeader = req.header("MTA-STS-Version");

  if (daneHeader || mtastsHeader) {
    next();
    return;
  }

  // If neither HTTPS nor DANE/MTA-STS, reject
  res.status(403).send("TLS required for mail transport");
}

