  quantity: string;
}

// Schema setup
const createTablesSql = `
  CREATE TABLE IF NOT EXISTS recipes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    prep_time INTEGER,
    cook_time INTEGER
  );

  CREATE TABLE IF NOT EXISTS ingredients (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    recipe_id INTEGER,
    name TEXT NOT NULL,
    quantity TEXT,
    FOREIGN KEY (recipe_id) REFERENCES recipes (id)
  );
`;

db.exec(createTablesSql);

// Query functions
export function getAllRecipes(): Recipe[] {
  const stmt = db.prepare(`
    SELECT * FROM recipes
  `);
  return stmt.all() as unknown as Recipe[];
}

export function getRecipeById(id: number): Recipe | undefined {
  const stmt = db.prepare(`
    SELECT * FROM recipes WHERE id = ?
  `);
  return stmt.get(id) as Recipe | undefined;
}

export function insertRecipe(
  title: string,
  description: string,
  prep_time: number,
  cook_time: number
): number {
  const stmt = db.prepare(`
    INSERT INTO recipes (title, description, prep_time, cook_time)
    VALUES (?, ?, ?, ?)
  `);
  const result = stmt.run(title, description, prep_time, cook_time);
  return Number(result.lastInsertRowid);
}

export function updateRecipe(
  id: number,
  title: string,
  description: string,
  prep_time: number,
  cook_time: number
): void {
  const stmt = db.prepare(`
    UPDATE recipes
    SET title = ?, description = ?, prep_time = ?, cook_time = ?
    WHERE id = ?
  `);
  stmt.run(title, description, prep_time, cook_time, id);
}

export function deleteRecipe(id: number): void {
  const stmt = db.prepare(`
    DELETE FROM recipes WHERE id = ?
  `);
  stmt.run(id);
}

export function getAllIngredients(): Ingredient[] {
  const stmt = db.prepare(`
    SELECT * FROM ingredients
  `);
  return stmt.all() as unknown as Ingredient[];
}

export function getIngredientsByRecipeId(recipeId: number): Ingredient[] {
  const stmt = db.prepare(`
    SELECT * FROM ingredients WHERE recipe_id = ?
  `);
  return stmt.all(recipeId) as unknown as Ingredient[];
}

export function insertIngredient(
  recipe_id: number,
  name: string,
  quantity: string
): number {
  const stmt = db.prepare(`
    INSERT INTO ingredients (recipe_id, name, quantity)
    VALUES (?, ?, ?)
  `);
  const result = stmt.run(recipe_id, name, quantity);
  return Number(result.lastInsertRowid);
}

