router.put("/recipes/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid recipe ID" });
    }

    const { title, description, prep_time, cook_time } = req.body;

    if (!title || !description || prep_time === undefined || cook_time === undefined) {
      return res.status(400).json({ error: "Missing required fields: title, description, prep_time, cook_time" });
    }

    const existingRecipe = getRecipeById(id);
    if (!existingRecipe) {
      return res.status(404).json({ error: "Recipe not found" });
    }

    updateRecipe(id, title, description, prep_time, cook_time);
    const updatedRecipe = getRecipeById(id);

    if (!updatedRecipe) {
      return res.status(500).json({ error: "Failed to update recipe" });
    }

    res.json(updatedRecipe);
