        const data = await response.json();
        setSessionData(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchSession();
  }, []);

  const handleCreateSession = async () => {
    try {
      const response = await fetch(`/api/conferencing-server/create-session`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({}),
      });
      if (!response.ok) throw new Error(`Failed to create session: ${await response.text()}`);
      const data = await response.json();
      setNewSessionId(data.id);
      // Refresh session list
      const refreshResponse = await fetch(`/api/conferencing-server/`);
      if (refreshResponse.ok) {
        const refreshedData = await refreshResponse.json();
        setSessionData(refreshedData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleJoinSession = async (id: string) => {
    try {
