import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/var/lib/sso-gateway/auth-sessions.db"
);

export interface AuthSession {
  id: number;
  user_id: number;
  session_token: string;
  refresh_token: string;
  expires_at: string;
  created_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS auth_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    session_token TEXT UNIQUE NOT NULL,
    refresh_token TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    created_at TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllSessions(): AuthSession[] {
  const stmt = db.prepare(
    "SELECT * FROM auth_sessions ORDER BY created_at DESC;"
  );
  return stmt.all() as unknown as AuthSession[];
}

export function getSessionById(id: number): AuthSession | undefined {
  const stmt = db.prepare(
    "SELECT * FROM auth_sessions WHERE id = ?;"
  );
  return stmt.get(id) as unknown as AuthSession | undefined;
}

export function insertSession(
  userId: number,
  sessionToken: string,
  refreshToken: string,
  expiresAt: string
): number {
  const stmt = db.prepare(
    "INSERT INTO auth_sessions (user_id, session_token, refresh_token, expires_at, created_at) VALUES (?, ?, ?, ?, datetime('now'));"
  );
  const result = stmt.run(userId, sessionToken, refreshToken, expiresAt);
  return Number(result.lastInsertRowid);
}

export function updateSession(
  id: number,
  userId: number,
  sessionToken: string,
  refreshToken: string,
  expiresAt: string
): void {
  const stmt = db.prepare(
    "UPDATE auth_sessions SET user_id = ?, session_token = ?, refresh_token = ?, expires_at = ? WHERE id = ?;"
  );
  stmt.run(userId, sessionToken, refreshToken, expiresAt, id);
}

export function deleteSession(id: number): void {
  const stmt = db.prepare("DELETE FROM auth_sessions WHERE id = ?;");
  stmt.run(id);
}

