import { createHmac, timingSafeEqual } from "node:crypto";

/**
 * Fine-grained access policy middleware for SSO gateway.
 * 
 * This middleware enforces access rules based on:
 * - Domain
 * - User group
 * - URI path
 * - HTTP method
 * - Network location (IP address)
 * 
 * It should be mounted globally to run on every request.
 */
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected routes or methods
  const protectedPaths = ["/api", "/admin"];
  const protectedMethods = ["POST", "PUT", "DELETE"];

  const isProtectedPath = protectedPaths.some(path => 
    req.path.startsWith(path)
  );

  if (!isProtectedPath || !protectedMethods.includes(req.method)) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token validation (in a real system, this would be more robust)
  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, "base64url"),
      Buffer.from(expectedSignature, "base64url")
    );

    if (!isValid) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // In a real implementation, we would decode the payload here
    // and check domain, user group, URI, method, and IP against policies

    // For now, we'll just pass through valid tokens
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Token verification failed" });
  }
}

