    topic TEXT NOT NULL,
    message TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  )
`;

db.exec(createTableSql);

export function insertMessageCache(
  topic: string,
  message: string
): number {
  const sql =
    "INSERT INTO message_cache (topic, message) VALUES (?, ?)";
  const result = db.prepare(sql).run(topic, message);
  return Number(result.lastInsertRowid);
}

export function getMessageCacheByTopic(
  topic: string
): MessageCacheRow[] {
  const sql =
    "SELECT * FROM message_cache WHERE topic = ? ORDER BY created_at DESC";
  return db.prepare(sql).all(topic) as unknown as MessageCacheRow[];
}

export function deleteMessageCacheById(id: number): void {
  const sql = "DELETE FROM message_cache WHERE id = ?";
  db.prepare(sql).run(id);
}

