import { Router, type Request, type Response } from "express";
import { db, deleteMessageCacheById, getMessageCacheByTopic, insertMessageCache } from "../db/message-cache-table";

export const router = Router();

// Handle POST and PUT requests to publish notifications
router.put("/publish/:topic", (req: Request, res: Response) => {
  const { topic } = req.params;
  const { message } = req.body;

  if (!topic || !message) {
    return res.status(400).json({ error: "Topic and message are required" });
  }

  try {
    const messageId = insertMessageCache(topic, message);
    return res.status(201).json({ id: messageId, topic, message });
  } catch (error) {
    return res.status(500).json({ error: "Failed to store message" });
  }
});

router.post("/publish/:topic", (req: Request, res: Response) => {
