  const { message } = req.body;

  if (!topic || !message) {
    return res.status(400).json({ error: "Topic and message are required" });
  }

  try {
    const messageId = insertMessageCache(topic, message);
    return res.status(201).json({ id: messageId, topic, message });
  } catch (error) {
    return res.status(500).json({ error: "Failed to store message" });
  }
});

// Get all messages for a specific topic
router.get("/topic/:topic", (req: Request, res: Response) => {
  const { topic } = req.params;

  if (!topic) {
    return res.status(400).json({ error: "Topic is required" });
  }

  try {
    const messages = getMessageCacheByTopic(topic);
    return res.json(messages);
  } catch (error) {
    return res.status(500).json({ error: "Failed to retrieve messages" });
  }
});

// Delete a specific message by ID
router.delete("/message/:id", (req: Request, res: Response) => {
  const { id } = req.params;

  if (!id) {
    return res.status(400).json({ error: "Message ID is required" });
  }

  try {
    const numericId = Number(id);
    if (isNaN(numericId)) {
      return res.status(400).json({ error: "Invalid message ID" });
    }

    const existingMessage = db.prepare("SELECT * FROM message_cache WHERE id = ?").get(numericId);
    if (!existingMessage) {
      return res.status(404).json({ error: "Message not found" });
    }

    deleteMessageCacheById(numericId);
    return res.json({ message: "Message deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete message" });
  }
});

