}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS assets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    purchaseDate TEXT NOT NULL,
    owner TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllAssets(): Asset[] {
  const stmt = db.prepare("SELECT * FROM assets");
  return stmt.all() as unknown as Asset[];
}

export function getAssetById(id: number): Asset | undefined {
  const stmt = db.prepare("SELECT * FROM assets WHERE id = ?");
  return stmt.get(id) as unknown as Asset | undefined;
}

export function insertAsset(name: string, purchaseDate: string, owner: string): number {
  const stmt = db.prepare(
    "INSERT INTO assets (name, purchaseDate, owner) VALUES (?, ?, ?)"
  );
  const result = stmt.run(name, purchaseDate, owner);
  return Number(result.lastInsertRowid);
}

export function updateAsset(id: number, name: string, purchaseDate: string, owner: string): number {
  const stmt = db.prepare(
    "UPDATE assets SET name = ?, purchaseDate = ?, owner = ? WHERE id = ?"
  );
  const result = stmt.run(name, purchaseDate, owner, id);
  return Number(result.changes);
}

export function deleteAsset(id: number): number {
  const stmt = db.prepare("DELETE FROM assets WHERE id = ?");
  const result = stmt.run(id);
  return Number(result.changes);
}

