export const router = Router();

// Search books by title, author, or ISBN
router.get("/", (req: Request, res: Response) => {
  const { title, author, isbn } = req.query;

  // Validate query parameters
  if (!title && !author && !isbn) {
    return res.status(400).json({ error: "At least one search parameter (title, author, or isbn) is required." });
  }

  // Get all books from the database
  const allBooks = getAllBooks();

  // Filter books based on search criteria
  let filteredBooks = allBooks;

  if (title) {
    filteredBooks = filteredBooks.filter(book => 
      book.title.toLowerCase().includes(title.toString().toLowerCase())
    );
  }

  if (author) {
    filteredBooks = filteredBooks.filter(book => 
      book.author.toLowerCase().includes(author.toString().toLowerCase())
    );
  }

  if (isbn) {
    filteredBooks = filteredBooks.filter(book => 
      book.isbn.includes(isbn.toString())
    );
  }

  // Return the filtered results
  res.json(filteredBooks);
});

