    title TEXT NOT NULL,
    content TEXT NOT NULL,
    owner_id INTEGER NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllPages(): Page[] {
  const stmt = db.prepare("SELECT * FROM pages");
  return stmt.all() as unknown as Page[];
}

export function getPageById(id: number): Page | undefined {
  const stmt = db.prepare("SELECT * FROM pages WHERE id = ?");
  return stmt.get(id) as unknown as Page | undefined;
}

export function insertPage(page: Omit<Page, "id" | "created_at" | "updated_at"): number {
  const stmt = db.prepare(
    "INSERT INTO pages (title, content, owner_id, created_at, updated_at) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(
    page.title,
    page.content,
    page.owner_id,
    new Date().toISOString(),
    new Date().toISOString()
  );
  return Number(result.lastInsertRowid);
}

export function updatePage(id: number, page: Omit<Page, "id" | "created_at" | "updated_at"): boolean {
  const stmt = db.prepare(
    "UPDATE pages SET title = ?, content = ?, owner_id = ?, updated_at = ? WHERE id = ?"
  );
  const result = stmt.run(
    page.title,
    page.content,
    page.owner_id,
    new Date().toISOString(),
    id
  );
  return result.changes > 0;
}

export function deletePage(id: number): boolean {
  const stmt = db.prepare("DELETE FROM pages WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

