import { Router, type Request, type Response } from "express";
import { db, deletePage, getAllPages, getPageById, insertPage, updatePage } from "../db/pages-table";

export const router = Router();

// Get all pages
router.get("/", (req: Request, res: Response) => {
  try {
    const pages = getAllPages();
    res.json(pages);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch pages" });
  }
});

// Get a specific page by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const page = getPageById(id);

    if (!page) {
      return res.status(404).json({ error: "Page not found" });
    }

    res.json(page);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch page" });
  }
});

// Create a new page
router.post("/", (req: Request, res: Response) => {
  try {
    const { title, content, owner_id } = req.body;

    if (!title || !content || !owner_id) {
      return res.status(400).json({ error: "Title, content, and owner_id are required" });
    }

    const newId = insertPage({ title, content, owner_id });

    // Fetch the created page to send back
    const newPage = getPageById(newId);

    if (!newPage) {
      return res.status(500).json({ error: "Failed to retrieve created page" });
    }

    res.status(201).json(newPage);
  } catch (error) {
    res.status(500).json({ error: "Failed to create page" });
  }
});

// Update an existing page
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { title, content, owner_id } = req.body;

    if (!title || !content || !owner_id) {
      return res.status(400).json({ error: "Title, content, and owner_id are required" });
    }

    const updatedRows = updatePage(id, { title, content, owner_id });

    if (!updatedRows) {
      return res.status(404).json({ error: "Page not found" });
    }

    // Fetch the updated page to send back
    const updatedPage = getPageById(id);

    if (!updatedPage) {
      return res.status(500).json({ error: "Failed to retrieve updated page" });
    }

    res.json(updatedPage);
  } catch (error) {
    res.status(500).json({ error: "Failed to update page" });
  }
});

// Delete a page
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const deleted = deletePage(id);

    if (!deleted) {
      return res.status(404).json({ error: "Page not found" });
    }

    res.json({ message: "Page deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete page" });
  }
});

