});

import { FC, useEffect, useState } from "react";

interface Habit {
  id: string;
  name: string;
}

interface HabitLog {
  id: string;
  date: string;
  habitIds: string[];
}

export function HabitLogForm() {
  const [habits, setHabits] = useState<Habit[]>([]);
  const [logs, setLogs] = useState<HabitLog[]>([]);
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [selectedHabits, setSelectedHabits] = useState<string[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchHabits = async () => {
      try {
        const response = await fetch('/api/habits-api/');
        if (!response.ok) throw new Error('Failed to fetch habits');
        const data = await response.json();
        setHabits(data);
      } catch (err) {
        setError('Failed to load habits');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    const fetchLogs = async () => {
      try {
        const response = await fetch(`/api/habits-api/123/${selectedDate}`);
        if (!response.ok) throw new Error('Failed to fetch logs');
        const data = await response.json();
        setLogs(data);
      } catch (err) {
        setError('Failed to load logs');
        console.error(err);
      }
    };

    fetchHabits();
    fetchLogs();
  }, [selectedDate]);

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSelectedDate(e.target.value);
  };

  const handleHabitToggle = (habitId: string) => {
    setSelectedHabits(prev => 
      prev.includes(habitId)
        ? prev.filter(id => id !== habitId)
        : [...prev, habitId]
    );
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch('/api/habits-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          date: selectedDate,
          habitIds: selectedHabits
        })
      });

      if (!response.ok) throw new Error('Failed to save log');

      // Refresh data after successful submission
      const logsResponse = await fetch(`/api/habits-api/123/${selectedDate}`);
      if (logsResponse.ok) {
        const logsData = await logsResponse.json();
        setLogs(logsData);
      }

      setSelectedHabits([]);
    } catch (err) {
      setError('Failed to save log');
      console.error(err);
    }
  };

  const handleDelete = async (logId: string) => {
    try {
      const response = await fetch(`/api/habits-api/${logId}`, {
        method: 'DELETE'
      });

      if (!response.ok) throw new Error('Failed to delete log');

      // Refresh data after successful deletion
      const logsResponse = await fetch(`/api/habits-api/123/${selectedDate}`);
      if (logsResponse.ok) {
        const logsData = await logsResponse.json();
        setLogs(logsData);
      }
    } catch (err) {
      setError('Failed to delete log');
      console.error(err);
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  return (
    <div style={{
      maxWidth: '600px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <h1>Habit Log</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: '20px' }}>
        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="date" style={{ display: 'block', marginBottom: '5px' }}>
            Date:
          </label>
          <input
            type="date"
            id="date"
            value={selectedDate}
            onChange={handleDateChange}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>
            Habits:
          </label>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
            {habits.map(habit => (
              <div key={habit.id} style={{ display: 'flex', alignItems: 'center' }}>
                <input
                  type="checkbox"
                  id={`habit-${habit.id}`}
                  checked={selectedHabits.includes(habit.id)}
                  onChange={() => handleHabitToggle(habit.id)}
                  style={{ marginRight: '5px' }}
                />
                <label htmlFor={`habit-${habit.id}`}>{habit.name}</label>
              </div>
            ))}
          </div>
        </div>

        <button 
          type="submit" 
          style={{
            backgroundColor: '#007bff',
