            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div>
          <label htmlFor="sessionDate" style={{ display: "block", marginBottom: "5px" }}>
            Session Date:
          </label>
          <input
            id="sessionDate"
            name="sessionDate"
            type="date"
            value={formData.sessionDate}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div>
          <label htmlFor="parentContact" style={{ display: "block", marginBottom: "5px" }}>
            Parent Contact Info:
          </label>
          <input
            id="parentContact"
            name="parentContact"
            type="text"
