import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "backend/src/db/volunteer-shift-signup.db"
);

interface ShiftVolunteerRow {
  volunteer_id: number;
  shift_id: number;
  signup_timestamp: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS shift_volunteers (
    volunteer_id INTEGER NOT NULL,
    shift_id INTEGER NOT NULL,
    signup_timestamp TEXT NOT NULL,
    PRIMARY KEY (volunteer_id, shift_id),
    FOREIGN KEY (volunteer_id) REFERENCES volunteers(id),
    FOREIGN KEY (shift_id) REFERENCES shifts(id)
  )
`;

db.exec(createTableSql);

export function getAllShiftVolunteers(): ShiftVolunteerRow[] {
  const stmt = db.prepare(
    "SELECT * FROM shift_volunteers"
  );
  return stmt.all() as unknown as ShiftVolunteerRow[];
}

export function getShiftVolunteerById(
  volunteerId: number,
  shiftId: number
): ShiftVolunteerRow | undefined {
  const stmt = db.prepare(
    "SELECT * FROM shift_volunteers WHERE volunteer_id = ? AND shift_id = ?"
  );
  return stmt.get(volunteerId, shiftId) as unknown as ShiftVolunteerRow | undefined;
}

export function insertShiftVolunteer(
  volunteerId: number,
  shiftId: number,
  signupTimestamp: string
): number {
  const stmt = db.prepare(
    "INSERT INTO shift_volunteers (volunteer_id, shift_id, signup_timestamp) VALUES (?, ?, ?)"
  );
  const result = stmt.run(volunteerId, shiftId, signupTimestamp);
  return Number(result.lastInsertRowid);
}

export function updateShiftVolunteer(
  volunteerId: number,
  shiftId: number,
  signupTimestamp: string
): number {
  const stmt = db.prepare(
    "UPDATE shift_volunteers SET signup_timestamp = ? WHERE volunteer_id = ? AND shift_id = ?"
  );
  const result = stmt.run(signupTimestamp, volunteerId, shiftId);
  return Number(result.changes);
}

export function deleteShiftVolunteer(
  volunteerId: number,
  shiftId: number
): number {
  const stmt = db.prepare(
    "DELETE FROM shift_volunteers WHERE volunteer_id = ? AND shift_id = ?"
  );
  const result = stmt.run(volunteerId, shiftId);
  return Number(result.changes);
}

