import { Router, type Request, type Response } from "express";
import {
  db,
  deleteShiftVolunteer,
  getAllShiftVolunteers,
  getShiftVolunteerById,
  insertShiftVolunteer,
  updateShiftVolunteer
} from "../db/shift-volunteers-table";

export const router = Router();

// GET /shifts - Get all shift volunteers
router.get("/shifts", (_req: Request, res: Response) => {
  const shiftVolunteers = getAllShiftVolunteers();
  res.json(shiftVolunteers);
});

// GET /shifts/:volunteerId/:shiftId - Get a specific shift volunteer by IDs
router.get("/shifts/:volunteerId/:shiftId", (req: Request, res: Response) => {
  const volunteerId = Number(req.params.volunteerId);
  const shiftId = Number(req.params.shiftId);

  if (isNaN(volunteerId) || isNaN(shiftId)) {
    return res.status(400).json({ error: "Invalid volunteerId or shiftId" });
  }

  const shiftVolunteer = getShiftVolunteerById(volunteerId, shiftId);

  if (!shiftVolunteer) {
    return res.status(404).json({ error: "Shift volunteer not found" });
  }

  res.json(shiftVolunteer);
});

// POST /shifts - Create a new shift volunteer
router.post("/shifts", (req: Request, res: Response) => {
  const { volunteerId, shiftId, signupTimestamp } = req.body;

  if (!volunteerId || !shiftId || !signupTimestamp) {
    return res.status(400).json({ error: "Missing required fields: volunteerId, shiftId, signupTimestamp" });
  }

  const newId = insertShiftVolunteer(
    Number(volunteerId),
    Number(shiftId),
    signupTimestamp
  );

  res.status(201).json({ id: newId });
});

// PUT /shifts/:volunteerId/:shiftId - Update a shift volunteer
router.put("/shifts/:volunteerId/:shiftId", (req: Request, res: Response) => {
  const volunteerId = Number(req.params.volunteerId);
  const shiftId = Number(req.params.shiftId);
  const { signupTimestamp } = req.body;

  if (isNaN(volunteerId) || isNaN(shiftId)) {
    return res.status(400).json({ error: "Invalid volunteerId or shiftId" });
  }

  if (!signupTimestamp) {
    return res.status(400).json({ error: "Missing required field: signupTimestamp" });
  }

  const updatedRows = updateShiftVolunteer(volunteerId, shiftId, signupTimestamp);

  if (updatedRows === 0) {
    return res.status(404).json({ error: "Shift volunteer not found" });
  }

  res.json({ message: "Shift volunteer updated successfully" });
});

// DELETE /shifts/:volunteerId/:shiftId - Delete a shift volunteer
router.delete("/shifts/:volunteerId/:shiftId", (req: Request, res: Response) => {
  const volunteerId = Number(req.params.volunteerId);
  const shiftId = Number(req.params.shiftId);

  if (isNaN(volunteerId) || isNaN(shiftId)) {
    return res.status(400).json({ error: "Invalid volunteerId or shiftId" });
  }

  const deletedRows = deleteShiftVolunteer(volunteerId, shiftId);

  if (deletedRows === 0) {
    return res.status(404).json({ error: "Shift volunteer not found" });
  }

  res.json({ message: "Shift volunteer deleted successfully" });
});

