// Inventory Items Routes
router.get("/inventory", (req: Request, res: Response) => {
  try {
    const items = getAllInventoryItems();
    res.json(items);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch inventory items" });
  }
});

router.get("/inventory/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const item = getInventoryItemById(id);
    if (!item) {
      return res.status(404).json({ error: "Inventory item not found" });
    }

    res.json(item);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch inventory item" });
  }
});

router.post("/inventory", (req: Request, res: Response) => {
  try {
    const { name, quantity, donorId, volunteerId } = req.body;

    if (!name || quantity === undefined) {
      return res.status(400).json({ error: "Name and quantity are required" });
    }

    const newId = insertInventoryItem(name, quantity, donorId || null, volunteerId || null);
    const newItem = getInventoryItemById(newId);

    if (!newItem) {
      return res.status(500).json({ error: "Failed to create inventory item" });
    }

    res.status(201).json(newItem);
  } catch (error) {
    res.status(500).json({ error: "Failed to create inventory item" });
  }
});

router.put("/inventory/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const { name, quantity, donorId, volunteerId } = req.body;

    if (!name || quantity === undefined) {
      return res.status(400).json({ error: "Name and quantity are required" });
    }

    const existingItem = getInventoryItemById(id);
    if (!existingItem) {
      return res.status(404).json({ error: "Inventory item not found" });
    }

    updateInventoryItem(id, name, quantity, donorId || null, volunteerId || null);
    const updatedItem = getInventoryItemById(id);

    if (!updatedItem) {
      return res.status(500).json({ error: "Failed to update inventory item" });
    }

    res.json(updatedItem);
  } catch (error) {
    res.status(500).json({ error: "Failed to update inventory item" });
  }
});

router.delete("/inventory/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const existingItem = getInventoryItemById(id);
    if (!existingItem) {
      return res.status(404).json({ error: "Inventory item not found" });
    }

    deleteInventoryItem(id);
    res.json({ message: "Inventory item deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete inventory item" });
  }
});

