import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as inventoryApiRouter } from "../routes/inventory-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check withdrawal requests
  if (!(req.method === "POST" && req.path.startsWith("/inventory/withdraw"))) {
    next();
    return;
  }

  // Check if withdrawal amount is large (for example, > 100 units)
  const amount = Number(req.body.amount);
  if (amount <= 100) {
    next();
    return;
  }

  // Check for approval token in headers
  const approvalToken = req.headers["x-approval-token"];
  if (!approvalToken || typeof approvalToken !== "string") {
    res.status(403).json({ error: "Large withdrawal requires site lead approval." });
    return;
  }

  // Verify the approval token (simple HMAC verification for demo purposes)
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error." });
    return;
  }

  const expectedToken = createHmac("sha256", secret)
    .update(amount.toString())
    .digest("hex");

  const expectedBuffer = Buffer.from(expectedToken);
  const providedBuffer = Buffer.from(approvalToken);

  try {
    if (timingSafeEqual(expectedBuffer, providedBuffer)) {
      next();
    } else {
      res.status(403).json({ error: "Invalid approval token." });
    }
  } catch (err) {
    res.status(403).json({ error: "Invalid approval token." });
  }
}

import { useEffect, useState } from "react";

interface InventoryItem {
  id: number;
  name: string;
  quantity: number;
  unit: string;
  expiryDate?: string;
}

interface FormData {
  name: string;
  quantity: string;
  unit: string;
  expiryDate?: string;
}

export function InventoryLogForm() {
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<FormData>({
    name: "",
    quantity: "",
    unit: "",
    expiryDate: ""
  });

  useEffect(() => {
    fetchInventory();
  }, []);

  const fetchInventory = async () => {
    try {
      const response = await fetch("/api/inventory-api/inventory");
      if (!response.ok) throw new Error("Failed to fetch inventory");
      const data = await response.json();
      setInventory(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/inventory-api/inventory", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...formData,
          quantity: Number(formData.quantity)
        })
      });

      if (!response.ok) throw new Error("Failed to add item");

      // Reset form
      setFormData({
        name: "",
        quantity: "",
        unit: "",
        expiryDate: ""
      });

      // Refresh inventory
      await fetchInventory();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  const inputStyle = {
    width: "100%",
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    boxSizing: "border-box"
  };

  const gridStyle = {
    display: "flex",
    flexWrap: "wrap",
    gap: "16px"
  };

  const cardStyle = {
    border: "1px solid #ddd",
    borderRadius: "8px",
    padding: "16px",
    width: "100%",
    boxSizing: "border-box"
  };

  return (
    <div style={{
      maxWidth: "800px",
      margin: "0 auto",
      padding: "16px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
    }}>
      <h1>Inventory Log Form</h1>

      <form onSubmit={handleSubmit} style={gridStyle}>
        <div style={cardStyle}>
          <h2>Add New Item</h2>
          <div style={{ marginBottom: "16px" }}>
            <label htmlFor="name">Name:</label><br />
            <input
              type="text"
              id="name"
              name="name"
              value={formData.name}
              onChange={handleInputChange}
              style={inputStyle}
              required
            />
          </div>

          <div style={{ marginBottom: "16px" }}>
            <label htmlFor="quantity">Quantity:</label><br />
            <input
              type="number"
              id="quantity"
              name="quantity"
              value={formData.quantity}
              onChange={handleInputChange}
              style={inputStyle}
              required
            />
          </div>

          <div style={{ marginBottom: "16px" }}>
            <label htmlFor="unit">Unit:</label><br />
            <input
              type="text"
              id="unit"
              name="unit"
              value={formData.unit}
              onChange={handleInputChange}
              style={inputStyle}
              required
            />
          </div>

          <div style={{ marginBottom: "16px" }}>
            <label htmlFor="expiryDate">Expiry Date (optional):</label><br />
            <input
              type="date"
              id="expiryDate"
              name="expiryDate"
              value={formData.expiryDate}
              onChange={handleInputChange}
              style={inputStyle}
            />
          </div>

          <button type="submit" style={{
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            padding: "10px 16px",
            borderRadius: "4px",
            cursor: "pointer"
          }}>Add Item</button>
        </div>
      </form>

      <h2>Current Inventory</h2>
      {inventory.length === 0 ? (
        <p>No items in inventory.</p>
      ) : (
        <div style={gridStyle}>
          {inventory.map(item => (
            <div key={item.id} style={cardStyle}>
              <strong>{item.name}</strong><br />
              Quantity: {item.quantity} {item.unit}<br />
              {item.expiryDate && `Expires: ${item.expiryDate}`}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface Withdrawal {
  id: number;
  item_id: number;
  quantity: number;
  status: "pending" | "approved" | "rejected";
  created_at: string;
}

interface InventoryItem {
  id: number;
  name: string;
  quantity: number;
  unit: string;
}

export function ApprovalQueue() {
  const [withdrawals, setWithdrawals] = useState<Withdrawal[]>([]);
  const [inventoryItems, setInventoryItems] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchAllData() {
      try {
        setLoading(true);
        const [withdrawalsRes, inventoryRes] = await Promise.all([
          fetch("/api/inventory-api/withdrawals?status=pending"),
          fetch("/api/inventory-api/inventory"),
        ]);

        if (!withdrawalsRes.ok || !inventoryRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const withdrawalsData = await withdrawalsRes.json();
        const inventoryData = await inventoryRes.json();

        setWithdrawals(withdrawalsData);
        setInventoryItems(inventoryData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchAllData();
  }, []);

  const handleApprove = async (id: number) => {
    try {
      const res = await fetch(`/api/inventory-api/withdrawals/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "approved" }),
      });

      if (!res.ok) {
        throw new Error("Failed to approve withdrawal");
      }

      // Refresh data
      const [withdrawalsRes, inventoryRes] = await Promise.all([
        fetch("/api/inventory-api/withdrawals?status=pending"),
        fetch("/api/inventory-api/inventory"),
      ]);

      if (!withdrawalsRes.ok || !inventoryRes.ok) {
        throw new Error("Failed to refresh data after approval");
      }

      const withdrawalsData = await withdrawalsRes.json();
      const inventoryData = await inventoryRes.json();

      setWithdrawals(withdrawalsData);
      setInventoryItems(inventoryData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleReject = async (id: number) => {
    try {
      const res = await fetch(`/api/inventory-api/withdrawals/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "rejected" }),
      });

      if (!res.ok) {
        throw new Error("Failed to reject withdrawal");
      }

      // Refresh data
      const [withdrawalsRes, inventoryRes] = await Promise.all([
        fetch("/api/inventory-api/withdrawals?status=pending"),
        fetch("/api/inventory-api/inventory"),
      ]);

      if (!withdrawalsRes.ok || !inventoryRes.ok) {
        throw new Error("Failed to refresh data after rejection");
      }

      const withdrawalsData = await withdrawalsRes.json();
      const inventoryData = await inventoryRes.json();

      setWithdrawals(withdrawalsData);
      setInventoryItems(inventoryData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const getInventoryName = (itemId: number) => {
    const item = inventoryItems.find(i => i.id === itemId);
    return item ? item.name : "Unknown Item";
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (withdrawals.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No pending withdrawals to approve.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Pending Withdrawals</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {withdrawals.map((withdrawal) => (
          <div
            key={withdrawal.id}
            style={{
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "15px",
              display: "flex",
              flexDirection: "column",
              gap: "10px",
            }}
          >
            <div>
              <strong>{getInventoryName(withdrawal.item_id)}</strong>
            </div>
            <div>
              Quantity: {withdrawal.quantity}
            </div>
            <div>
              Requested on: {new Date(withdrawal.created_at).toLocaleDateString()}
            </div>
            <div
              style={{
                display: "flex",
                justifyContent: "flex-end",
                gap: "10px",
                flexWrap: "wrap",
              }}
            >
              <button
                onClick={() => handleApprove(withdrawal.id)}
                style={{
                  backgroundColor: "#4CAF50",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 16px",
                  cursor: "pointer",
                }}
              >
                Approve
              </button>
              <button
                onClick={() => handleReject(withdrawal.id)}
                style={{
                  backgroundColor: "#f44336",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 16px",
                  cursor: "pointer",
                }}
              >
                Reject
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

