import { Router, type Request, type Response } from "express";
import { db as bikesDb, deleteBike, getAllBikes, getBikeById } from "../db/bikes-table";
import { db as repairRecordsDb, deleteRepairRecord, getAllRepairRecords, getRepairRecordById } from "../db/repair-records-table";

export const router = Router();

router.delete("/bikes/:id", (req: Request, res: Response) => {
  // Check if user is fleet manager
  const userRole = req.headers["role"];
  if (userRole !== "fleet-manager") {
    return res.status(403).json({ error: "Access denied. Only fleet managers can retire bikes." });
  }

  const bikeId = Number(req.params.id);

  if (isNaN(bikeId)) {
    return res.status(400).json({ error: "Invalid bike ID." });
  }

  const bike = getBikeById(bikeId);
  if (!bike) {
    return res.status(404).json({ error: "Bike not found." });
  }

  // Check for associated repair records
  const repairRecords = getAllRepairRecords();
  const recordsForBike = repairRecords.filter((record: any) => record.bikeId === bikeId);

  // Delete all associated repair records
  recordsForBike.forEach((record: any) => {
    deleteRepairRecord(record.id);
  });

  // Delete the bike
  deleteBike(bikeId);

  return res.status(200).json({ message: "Bike retired successfully." });
});

import type { Request, Response, NextFunction } from "express";
import { router as bikesApiRouter } from "../routes/bikes-api";
import { router as retirementGuardRouter } from "../routes/retirement-guard";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check access for POST requests to the retirement guard endpoint
  if (req.method !== "POST" || !req.path.startsWith("/retire")) {
    next();
    return;
  }

  // Check if user has fleet-manager role
  // This is a placeholder - in a real implementation, you'd extract
  // the role from a JWT or session
