export function RepairLogForm() {
  const [bikes, setBikes] = useState<Array<{ id: number; name: string }>>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [bikeId, setBikeId] = useState("");
  const [partName, setPartName] = useState("");
  const [labourCost, setLabourCost] = useState("");

  useEffect(() => {
    fetchBikes();
  }, []);

  const fetchBikes = async () => {
    try {
      const response = await fetch("/api/bikes-api/bikes");
      if (!response.ok) {
        throw new Error(`Failed to fetch bikes: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setBikes(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!bikeId || !partName || !labourCost) {
      setError("All fields are required.");
      return;
