          fetch("/api/rehearsal-api/rehearsals"),
          fetch("/api/rehearsal-api/musicians"),
        ]);

        if (!rehearsalsRes.ok || !musiciansRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const [rehearsalsData, musiciansData] = await Promise.all([
          rehearsalsRes.json(),
          musiciansRes.json(),
        ]);

        setRehearsals(rehearsalsData);
        setMusicians(musiciansData);

        // Fetch attendances for each rehearsal
        const attendancePromises = rehearsalsData.map((r: Rehearsal) =>
          fetch(`/api/rehearsal-api/rehearsals/${r.id}/attendances`)
        );

        const attendanceResponses = await Promise.all(attendancePromises);
        const attendanceData = await Promise.all(
          attendanceResponses.map((res) => res.json())
        );

        setAttendances(attendanceData.flat());
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchAllData();
  }, []);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (rehearsals.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No rehearsals scheduled.
      </div>
    );
  }

  const getAttendanceForRehearsal = (rehearsalId: number) => {
    return attendances.filter((a) => a.rehearsalId === rehearsalId);
  };

  const getMusicianName = (musicianId: number) => {
    const musician = musicians.find((m) => m.id === musicianId);
    return musician ? musician.name : "Unknown Musician";
  };

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Upcoming Rehearsals</h1>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "20px",
        }}
      >
        {rehearsals.map((rehearsal) => (
          <div
            key={rehearsal.id}
            style={{
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "15px",
              backgroundColor: "#f9f9f9",
            }}
          >
            <h2>{rehearsal.date} at {rehearsal.time}</h2>
            <p>{rehearsal.location}</p>
            <h3>Attendees:</h3>
            <ul>
              {getAttendanceForRehearsal(rehearsal.id).length > 0 ? (
                getAttendanceForRehearsal(rehearsal.id).map((a) => (
                  <li key={`${rehearsal.id}-${a.musicianId}`}>
                    {getMusicianName(a.musicianId)} - {a.status}
                  </li>
                ))
              ) : (
                <li>No attendees recorded.</li>
              )}
            </ul>
          </div>
        ))}
      </div>
    </div>
  );
}

import { FC, useState } from "react";

interface Rehearsal {
  id: string;
  title: string;
  date: string;
  conductor: string;
}

export function ConductorOnlyCancelButton({
  rehearsalId,
  currentUserId,
  onRehearsalCancelled
}: {
  rehearsalId: string;
  currentUserId: string;
  onRehearsalCancelled: () => void;
}) {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleCancel() {
    setIsLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/rehearsal-api/rehearsals/${rehearsalId}`, {
        method: "DELETE",
        headers: {
          "Content-Type": "application/json"
        }
      });

      if (!response.ok) {
        throw new Error(`Failed to cancel rehearsal: ${response.status} ${response.statusText}`);
      }

      onRehearsalCancelled();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <div style={{ maxWidth: 600, margin: "0 auto", padding: 20, fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <button 
        onClick={handleCancel}
        disabled={isLoading}
        style={{
          backgroundColor: "#ff4d4d",
          color: "white",
          border: "none",
          borderRadius: 4,
          padding: "10px 20px",
          fontSize: 16,
          cursor: isLoading ? "not-allowed" : "pointer"
        }}
      >
        {isLoading ? "Cancelling..." : "Cancel Rehearsal"}
      </button>

      {error && (
        <div style={{ marginTop: 10, color: "#ff0000" }}>
          {error}
        </div>
      )}
    </div>
  );
}

import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./tutor-scheduler.db");

interface SessionRow {
  id: number;
  tutor_id: number;
  student_id: number;
  topic: string;
  completed_at: string | null;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    tutor_id INTEGER NOT NULL,
    student_id INTEGER NOT NULL,
    topic TEXT NOT NULL,
    completed_at TEXT
  )
`;

db.exec(createTableSql);

export function getAllSessions(): SessionRow[] {
  const stmt = db.prepare("SELECT * FROM sessions");
  return stmt.all() as unknown as SessionRow[];
}

export function getSessionById(id: number): SessionRow | undefined {
  const stmt = db.prepare("SELECT * FROM sessions WHERE id = ?");
  return stmt.get(id) as unknown as SessionRow | undefined;
}

export function insertSession(
  tutorId: number,
  studentId: number,
  topic: string,
  completedAt: string | null
): number {
  const stmt = db.prepare(
    "INSERT INTO sessions (tutor_id, student_id, topic, completed_at) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(tutorId, studentId, topic, completedAt);
  return Number(result.lastInsertRowid);
}

export function updateSession(
  id: number,
  tutorId: number,
  studentId: number,
  topic: string,
  completedAt: string | null
): void {
  const stmt = db.prepare(
    "UPDATE sessions SET tutor_id = ?, student_id = ?, topic = ?, completed_at = ? WHERE id = ?"
  );
  stmt.run(tutorId, studentId, topic, completedAt, id);
}

export function deleteSession(id: number): void {
  const stmt = db.prepare("DELETE FROM sessions WHERE id = ?");
  stmt.run(id);
}

