import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./tutor-scheduler.db");

interface BillingRate {
  id: number;
  subject_area: string;
  hourly_rate: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS billing_rates (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    subject_area TEXT NOT NULL UNIQUE,
    hourly_rate REAL NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllBillingRates(): BillingRate[] {
  const stmt = db.prepare(`SELECT * FROM billing_rates`);
  return stmt.all() as unknown as BillingRate[];
}

export function getBillingRateById(id: number): BillingRate | undefined {
  const stmt = db.prepare(`SELECT * FROM billing_rates WHERE id = ?`);
  return stmt.get(id) as unknown as BillingRate | undefined;
}

export function insertBillingRate(subjectArea: string, hourlyRate: number): number {
  const stmt = db.prepare(
    `INSERT INTO billing_rates (subject_area, hourly_rate) VALUES (?, ?)`
  );
  const result = stmt.run(subjectArea, hourlyRate);
  return Number(result.lastInsertRowid);
}

export function updateBillingRate(id: number, subjectArea: string, hourlyRate: number): number {
  const stmt = db.prepare(
    `UPDATE billing_rates SET subject_area = ?, hourly_rate = ? WHERE id = ?`
  );
  const result = stmt.run(subjectArea, hourlyRate, id);
  return Number(result.changes);
}

export function deleteBillingRate(id: number): number {
  const stmt = db.prepare(`DELETE FROM billing_rates WHERE id = ?`);
  const result = stmt.run(id);
  return Number(result.changes);
}

