import { Router, type Request, type Response } from "express";
import {
  getAllSessions,
  getSessionById,
  insertSession,
  updateSession,
  deleteSession
} from "../db/sessions-table";
import {
  getAllBillingRates,
  getBillingRateById,
  insertBillingRate,
  updateBillingRate,
  deleteBillingRate
} from "../db/billing-rates-table";

export const router = Router();

// GET /sessions - Get all sessions
router.get("/sessions", (req: Request, res: Response) => {
  try {
    const sessions = getAllSessions();
    res.json(sessions);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch sessions" });
  }
});

// GET /sessions/:id - Get a session by ID
router.get("/sessions/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const session = getSessionById(id);
    if (!session) {
      return res.status(404).json({ error: "Session not found" });
    }
    res.json(session);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch session" });
  }
});

// POST /sessions - Create a new session
router.post("/sessions", (req: Request, res: Response) => {
  try {
    const { tutorId, studentId, topic, completedAt } = req.body;
    if (!tutorId || !studentId || !topic) {
      return res.status(400).json({ error: "Missing required fields: tutorId, studentId, topic" });
    }
    const id = insertSession(tutorId, studentId, topic, completedAt || null);
    res.status(201).json({ id });
  } catch (error) {
    res.status(500).json({ error: "Failed to create session" });
  }
});

// PUT /sessions/:id - Update a session
router.put("/sessions/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { tutorId, studentId, topic, completedAt } = req.body;
    if (!tutorId || !studentId || !topic) {
      return res.status(400).json({ error: "Missing required fields: tutorId, studentId, topic" });
    }
    const existingSession = getSessionById(id);
    if (!existingSession) {
      return res.status(404).json({ error: "Session not found" });
    }
    updateSession(id, tutorId, studentId, topic, completedAt || null);
    res.json({ message: "Session updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update session" });
  }
});

// DELETE /sessions/:id - Delete a session
router.delete("/sessions/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const existingSession = getSessionById(id);
    if (!existingSession) {
      return res.status(404).json({ error: "Session not found" });
    }
    deleteSession(id);
    res.json({ message: "Session deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete session" });
  }
});

