import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as sessionsRouter } from "../routes/sessions-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply guard to billing-related requests
  if (!(req.method === "PATCH" && req.path.startsWith("/api/sessions/"))) {
    next();
    return;
  }

  // Check if user is director (mock implementation)
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Mock verification - in reality, you'd decode and verify the JWT signature
  // For this example, we'll just check if the token contains "director"
  if (token.includes("director")) {
    next();
  } else {
    res.status(403).json({ error: "Access denied: Director only" });
  }
}

