interface Role {
  id: number;
  user_id: number;
  role: "author" | "editor" | "admin";
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS roles (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    role TEXT NOT NULL CHECK(role IN ('author', 'editor', 'admin'))
  )
`;

db.exec(createTableSql);

export function getAllRoles(): Role[] {
  const stmt = db.prepare(`SELECT * FROM roles`);
  return stmt.all() as unknown as Role[];
}

export function getRoleById(id: number): Role | undefined {
  const stmt = db.prepare(`SELECT * FROM roles WHERE id = ?`);
  return stmt.get(id) as unknown as Role | undefined;
}

export function insertRole(userId: number, role: "author" | "editor" | "admin"): number {
  const stmt = db.prepare(
    `INSERT INTO roles (user_id, role) VALUES (?, ?)`
  );
  stmt.run(userId, role);
  const result = db.prepare(`SELECT last_insert_rowid() as id`).get();
  return Number(result.id);
}

export function updateRole(id: number, userId: number, role: "author" | "editor" | "admin"): boolean {
  const stmt = db.prepare(
    `UPDATE roles SET user_id = ?, role = ? WHERE id = ?`
  );
  stmt.run(userId, role, id);
  return stmt.changes > 0;
}

export function deleteRole(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM roles WHERE id = ?`);
  stmt.run(id);
  return stmt.changes > 0;
}

