import { Router, type Request, type Response } from "express";
import {
  getAllSubmissions,
  getSubmissionById,
  insertSubmission,
  updateSubmission,
  deleteSubmission
} from "../db/submissions-table";
import {
  getAllRoles,
  getRoleById
} from "../db/roles-table";
import {
  getAllSubmissionStatuses,
  getSubmissionStatusById
} from "../db/submission-status-table";
import {
  getAllSubmissionCategories,
  getSubmissionCategoryById
} from "../db/submission-categories-table";

export const router = Router();

// Get all submissions
router.get("/", (req: Request, res: Response) => {
  try {
    const submissions = getAllSubmissions();
    return res.json(submissions);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch submissions" });
  }
});

// Get a submission by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid submission ID" });
    }

    const submission = getSubmissionById(id);
    if (!submission) {
      return res.status(404).json({ error: "Submission not found" });
    }

    return res.json(submission);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch submission" });
  }
});

// Create a new submission
router.post("/", (req: Request, res: Response) => {
  try {
    const { content, authorId, category, reviewStatus } = req.body;

    if (!content || !authorId || !category || !reviewStatus) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    // Validate author role
    const userRole = getRoleById(authorId);
    if (!userRole || userRole.role !== "author") {
      return res.status(400).json({ error: "Author must have 'author' role" });
    }

    // Validate category exists
    const categories = getAllSubmissionCategories();
    const validCategory = categories.find(c => c.name === category);
    if (!validCategory) {
      return res.status(400).json({ error: "Invalid category" });
    }

    // Validate status exists
    const statuses = getAllSubmissionStatuses();
    const validStatus = statuses.find(s => s.name === reviewStatus);
    if (!validStatus) {
      return res.status(400).json({ error: "Invalid review status" });
    }

    const id = insertSubmission(content, authorId, category, reviewStatus);
    const newSubmission = getSubmissionById(id);

    if (!newSubmission) {
      return res.status(500).json({ error: "Failed to create submission" });
    }

    return res.status(201).json(newSubmission);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create submission" });
  }
});

// Update a submission
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid submission ID" });
    }

    const { content, authorId, category, reviewStatus } = req.body;

    if (!content || !authorId || !category || !reviewStatus) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    // Check if submission exists
    const existingSubmission = getSubmissionById(id);
    if (!existingSubmission) {
      return res.status(404).json({ error: "Submission not found" });
    }

    // Validate author role
    const userRole = getRoleById(authorId);
    if (!userRole || userRole.role !== "author") {
      return res.status(400).json({ error: "Author must have 'author' role" });
    }

    // Validate category exists
    const categories = getAllSubmissionCategories();
    const validCategory = categories.find(c => c.name === category);
    if (!validCategory) {
      return res.status(400).json({ error: "Invalid category" });
    }

    // Validate status exists
    const statuses = getAllSubmissionStatuses();
    const validStatus = statuses.find(s => s.name === reviewStatus);
    if (!validStatus) {
      return res.status(400).json({ error: "Invalid review status" });
    }

    updateSubmission(id, content, authorId, category, reviewStatus);
    const updatedSubmission = getSubmissionById(id);

    if (!updatedSubmission) {
      return res.status(500).json({ error: "Failed to update submission" });
    }

    return res.json(updatedSubmission);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update submission" });
  }
});

// Delete a submission
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid submission ID" });
    }

    const existingSubmission = getSubmissionById(id);
    if (!existingSubmission) {
      return res.status(404).json({ error: "Submission not found" });
    }

    deleteSubmission(id);
    return res.json({ message: "Submission deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete submission" });
  }
});

import { Router, type Request, type Response } from "express";
import { getSubmissionById, updateSubmission } from "../db/submissions-table";
import { getRoleById } from "../db/roles-table";

export const router = Router();

router.put("/:id/advance-to-review", (req: Request, res: Response) => {
  const submissionId = Number(req.params.id);

  if (isNaN(submissionId)) {
    return res.status(400).json({ error: "Invalid submission ID" });
  }

  const userRole = getRoleById(Number(req.body.userId));

  if (!userRole) {
    return res.status(404).json({ error: "User not found" });
  }

  if (userRole.role !== "editor" && userRole.role !== "admin") {
    return res.status(403).json({ error: "Access denied. Only editors and admins can advance submissions." });
  }

  const submission = getSubmissionById(submissionId);

  if (!submission) {
    return res.status(404).json({ error: "Submission not found" });
  }

  updateSubmission(submissionId, submission.content, submission.author_id, submission.category, "in_review");

  return res.json({ message: "Submission advanced to review" });
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access check to POST requests to /submissions/:id/advance
  if (req.method !== "POST" || !req.path.match(/^\/submissions\/[^\/]+\/advance$/)) {
    next();
    return;
  }

  // Check if user has required role (editor or admin)
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole || (userRole !== "editor" && userRole !== "admin")) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

import { useEffect, useState } from "react";

interface Submission {
  id: number;
  title: string;
  author: string;
  status: "submitted" | "under-review" | "approved" | "rejected";
  createdAt: string;
}

export function SubmissionQueue() {
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchSubmissions();
  }, []);

  const fetchSubmissions = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/submissions-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch submissions: ${response.status}`);
      }
      const data = await response.json();
      setSubmissions(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleAdvanceToReview = async (id: number) => {
    try {
      const response = await fetch(`/api/role-based-access-control/submissions/${id}/advance-to-review`, {
        method: "PUT",
      });
      if (!response.ok) {
        throw new Error(`Failed to advance submission: ${response.status}`);
      }
      await fetchSubmissions();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/submissions-api/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete submission: ${response.status}`);
      }
      await fetchSubmissions();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
