import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check approval requests, ignore all other routes/methods
  if (!(req.method === "POST" && req.path === "/api/approve-order")) {
    next();
    return;
  }

  // Check if user is a manager
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  const expectedSignature = createHmac("sha256", secret)
    .update(token.split(".")[0] + "." + token.split(".")[1])
    .digest();

  const actualSignature = Buffer.from(token.split(".")[2], "base64");

  try {
    const isValid = timingSafeEqual(expectedSignature, actualSignature);
    if (!isValid) {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // Check if user has manager role
  const payload = JSON.parse(Buffer.from(token.split(".")[1], "base64").toString());
  if (payload.role !== "manager") {
    res.status(403).json({ error: "Forbidden: Only managers can approve orders" });
    return;
  }

  next();
}

import { useEffect, useState } from "react";

interface PartRequest {
  id: string;
  partName: string;
  quantity: number;
  status: "pending" | "approved" | "rejected";
  requestedBy: string;
  requestedAt: string;
}

export function PartRequestQueue() {
  const [requests, setRequests] = useState<PartRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchRequests();
  }, []);

  const fetchRequests = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/parts-api/requests");
      if (!response.ok) {
        throw new Error(`Failed to fetch requests: ${response.status}`);
      }
      const data = await response.json();
      setRequests(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (id: string) => {
    try {
      const response = await fetch(`/api/parts-api/requests/${id}/status`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "approved" }),
      });

      if (!response.ok) {
        throw new Error(`Failed to approve request: ${response.status}`);
      }

      fetchRequests();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleReject = async (id: string) => {
    try {
      const response = await fetch(`/api/parts-api/requests/${id}/status`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "rejected" }),
      });

      if (!response.ok) {
        throw new Error(`Failed to reject request: ${response.status}`);
      }

      fetchRequests();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (requests.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No pending requests.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Part Request Queue</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {requests
          .filter((req) => req.status === "pending")
          .map((request) => (
            <div
              key={request.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                flexDirection: "column",
                gap: "10px",
              }}
            >
              <div>
                <strong>Part:</strong> {request.partName}
              </div>
              <div>
                <strong>Quantity:</strong> {request.quantity}
              </div>
              <div>
                <strong>Requested By:</strong> {request.requestedBy}
              </div>
              <div>
                <strong>Requested At:</strong> {new Date(request.requestedAt).toLocaleString()}
              </div>
              <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
                <button
                  onClick={() => handleApprove(request.id)}
                  style={{
                    backgroundColor: "#4CAF50",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Approve
                </button>
                <button
                  onClick={() => handleReject(request.id)}
                  style={{
                    backgroundColor: "#f44336",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Reject
                </button>
              </div>
            </div>
          ))}
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

export function LargeOrderGuard() {
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [threshold, setThreshold] = useState<number>(1000);

  useEffect(() => {
    fetchOrders();
  }, []);

  const fetchOrders = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/parts-api/requests');
      if (!response.ok) {
        throw new Error('Failed to fetch orders');
      }
      const data = await response.json();
      setOrders(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleThresholdChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = Number(e.target.value);
    if (!isNaN(value)) {
      setThreshold(value);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    // In a real implementation, this would submit the threshold
    // For now, we just show the threshold value
    alert(`Threshold updated to: $${threshold}`);
  };

  const getFilteredOrders = () => {
    return orders.filter(order => order.total > threshold);
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  const filteredOrders = getFilteredOrders();

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Large Order Guard</h1>
      <p>Rejects any part order over a configurable threshold.</p>

      <form onSubmit={handleSubmit} style={{ marginBottom: '20px' }}>
        <label htmlFor="threshold">Threshold: </label>
        <input
          id="threshold"
          type="number"
          value={threshold}
          onChange={handleThresholdChange}
          style={{ width: '100px', marginLeft: '10px' }}
        />
        <button type="submit" style={{ marginLeft: '10px', padding: '5px 10px' }}>Update</button>
      </form>

      <h2>Large Orders (Over ${threshold})</h2>
      {filteredOrders.length === 0 ? (
        <p>No large orders found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {filteredOrders.map((order) => (
            <div key={order.id} style={{ border: '1px solid #ccc', borderRadius: '5px', padding: '10px' }}>
              <strong>Order ID:</strong> {order.id}<br />
              <strong>Total:</strong> ${order.total}<br />
              <strong>Status:</strong> {order.status}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

