export const router = Router();

// Get all airtime slots
router.get("/", (req: Request, res: Response) => {
  try {
    const slots = getAllAirtimeSlots();
    return res.json(slots);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch airtime slots" });
  }
});

// Get a specific airtime slot by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid slot ID" });
    }

    const slot = getAirtimeSlotById(id);
    if (!slot) {
      return res.status(404).json({ error: "Airtime slot not found" });
    }

    return res.json(slot);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch airtime slot" });
  }
});

// Create a new airtime slot
router.post("/", (req: Request, res: Response) => {
  try {
    const { djId, startTime, endTime, programDirectorGuard } = req.body;

    if (!djId || !startTime || !endTime) {
      return res.status(400).json({ error: "Missing required fields: djId, startTime, endTime" });
    }

    const id = insertAirtimeSlot(
      Number(djId),
      startTime,
      endTime,
      programDirectorGuard === true
