    if (!djId || !startTime || !endTime) {
      return res.status(400).json({ error: "Missing required fields: djId, startTime, endTime" });
    }

    const existingSlot = getAirtimeSlotById(id);
    if (!existingSlot) {
      return res.status(404).json({ error: "Airtime slot not found" });
    }

    updateAirtimeSlot(
      id,
      Number(djId),
      startTime,
      endTime,
      programDirectorGuard === true
    );

    const updatedSlot = getAirtimeSlotById(id);
    if (!updatedSlot) {
      return res.status(500).json({ error: "Failed to retrieve updated airtime slot" });
    }

    return res.json(updatedSlot);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update airtime slot" });
  }
});

