import { FC, useEffect, useState } from "react";

interface Slot {
  id: string;
  djId: string;
  startTime: string;
  endTime: string;
}

interface Claim {
  id: string;
  slotId: string;
  djId: string;
}

export function PreemptionGuard() {
  const [slots, setSlots] = useState<Slot[]>([]);
  const [claims, setClaims] = useState<Claim[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentUserRole, setCurrentUserRole] = useState<string>("dj"); // Default to DJ role

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [slotsResponse, claimsResponse] = await Promise.all([
          fetch("/api/scheduling-api/"),
          fetch("/api/scheduling-api/claims")
        ]);

        if (!slotsResponse.ok || !claimsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const slotsData = await slotsResponse.json();
        const claimsData = await claimsResponse.json();

        setSlots(slotsData);
        setClaims(claimsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleClaim = async (slotId: string, djId: string) => {
    // Simulate checking if the current user is the program director
    if (currentUserRole !== "program-director") {
      // Check if slot is already claimed
      const existingClaim = claims.find(claim => claim.slotId === slotId);
      if (existingClaim && existingClaim.djId !== djId) {
        alert("This slot is already claimed by another DJ.");
        return;
      }
    }

    try {
      const response = await fetch(`/api/scheduling-api/claims`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ slotId, djId })
      });

      if (!response.ok) {
        throw new Error("Failed to claim slot");
      }

      // Refresh data after successful claim
      const [slotsResponse, claimsResponse] = await Promise.all([
        fetch("/api/scheduling-api/"),
        fetch("/api/scheduling-api/claims")
      ]);

      if (slotsResponse.ok && claimsResponse.ok) {
        const slotsData = await slotsResponse.json();
        const claimsData = await claimsResponse.json();
        setSlots(slotsData);
        setClaims(claimsData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Preemption Guard</h1>
      <p style={{ textAlign: "center" }}>Manage DJ slot claims with preemption protection</p>

      <div style={{ marginBottom: "20px" }}>
        <label htmlFor="userRole">User Role:</label>
        <select 
          id="userRole"
          value={currentUserRole}
          onChange={(e) => setCurrentUserRole(e.target.value)}
          style={{ marginLeft: "10px", padding: "5px" }}
        >
          <option value="dj">DJ</option>
          <option value="program-director">Program Director</option>
        </select>
      </div>

      <h2>Available Slots</h2>
      {slots.length === 0 ? (
        <p style={{ textAlign: "center" }}>No slots available.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
          {slots.map(slot => {
            const claim = claims.find(c => c.slotId === slot.id);
            return (
              <div 
                key={slot.id} 
                style={{ 
                  border: "1px solid #ccc", 
                  borderRadius: "8px", 
                  padding: "10px", 
                  minWidth: "200px", 
                  flex: "1 1 calc(50% - 10px)" 
                }}
              >
                <h3>{slot.startTime} - {slot.endTime}</h3>
                <p>DJ ID: {slot.djId}</p>
                <p>Status: {claim ? `Claimed by ${claim.djId}` : "Available"}</p>
                <button 
                  onClick={() => handleClaim(slot.id, slot.djId)}
                  disabled={!!claim}
                  style={{ 
                    backgroundColor: claim ? "#ccc" : "#007bff", 
                    color: "white", 
                    border: "none", 
                    padding: "5px 10px", 
                    borderRadius: "4px", 
                    cursor: claim ? "default" : "pointer" 
                  }}
                >
                  {claim ? "Already Claimed" : "Claim Slot"}
                </button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

