  const result = stmt.run(isManager, id);
  return result.changes > 0;
}

export function deleteManagerUser(userId: number): boolean {
  const stmt = db.prepare(`DELETE FROM manager_users WHERE user_id = ?`);
  const result = stmt.run(userId);
  return result.changes > 0;
}

