  date: string;
  startTime: string;
  endTime: string;
  isAvailable: boolean;
}

export function BookingCalendar() {
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/bookings-api/bookings');
      if (!response.ok) {
        throw new Error(`Failed to fetch bookings: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setTimeSlots(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (timeSlots.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No available time slots.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Kitchen Booking Calendar</h1>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
        {timeSlots
          .filter(slot => slot.isAvailable)
          .map(slot => (
            <div 
              key={slot.id}
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                width: '100%', 
                maxWidth: '300px'
              }}
            >
              <div style={{ fontWeight: 'bold' }}>{slot.date}</div>
              <div>{slot.startTime} - {slot.endTime}</div>
              <button 
                style={{ 
                  marginTop: '10px', 
                  backgroundColor: '#4CAF50', 
                  color: 'white', 
                  border: 'none', 
                  borderRadius: '4px', 
                  padding: '8px 12px', 
                  cursor: 'pointer', 
                  width: '100%'
                }}
                onClick={() => {
                  // In a real app, this would make a POST request to book the slot
                  alert(`Booking confirmed for ${slot.date} from ${slot.startTime} to ${slot.endTime}`);
                }}
              >
                Book Now
              </button>
            </div>
          ))}
      </div>
    </div>
  );
