  const [managers, setManagers] = useState<Manager[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchBookings() {
      try {
        const response = await fetch("/api/bookings-api/bookings");
        if (!response.ok) {
          throw new Error(`Failed to fetch bookings: ${response.status}`);
        }
        const data = await response.json();
        setBookings(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    async function fetchManagers() {
      try {
        const response = await fetch("/api/bookings-api/managers");
        if (!response.ok) {
          throw new Error(`Failed to fetch managers: ${response.status}`);
        }
        const data = await response.json();
        setManagers(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      }
    }

    fetchBookings();
    fetchManagers();
  }, []);

  const handleWaiverOverride = async (bookingId: string) => {
