import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to /recipes
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE") || !req.path.startsWith("/recipes")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT signature
  // For this example, we'll just check if it matches a hardcoded expected token
  // In practice, you'd use a proper JWT library like jsonwebtoken

  const expectedToken = createHmac("sha256", secret)
    .update("recipe-editor-token")
    .digest("hex");

  const expectedBuffer = Buffer.from(expectedToken);
  const providedBuffer = Buffer.from(token);

  try {
    if (timingSafeEqual(expectedBuffer, providedBuffer)) {
      next();
    } else {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

