  id: number;
  title: string;
  description: string;
  ingredients: Ingredient[];
  steps: Step[];
  tags: Tag[];
}

export function RecipeDetailView({
  recipeId,
}: {
  recipeId: string;
}) {
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchRecipe() {
      try {
        const response = await fetch(`/api/recipes-api/recipes/${recipeId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch recipe: ${response.status} ${response.statusText}`);
        }
        const data = await response.json();
        setRecipe(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchRecipe();
  }, [recipeId]);

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  if (!recipe) return <div style={{ textAlign: "center", padding: "20px" }}>Recipe not found</div>;

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center", marginBottom: "10px" }}>{recipe.title}</h1>
      <p style={{ textAlign: "center", marginBottom: "30px", color: "#666" }}>
        {recipe.description}
      </p>

      <div style={{ marginBottom: "30px" }}>
        <h2 style={{ marginBottom: "10px" }}>Ingredients</h2>
        <ul style={{ paddingLeft: "20px" }}>
          {recipe.ingredients.map((ingredient) => (
            <li key={ingredient.id} style={{ marginBottom: "5px" }}>
              {ingredient.amount} {ingredient.name}
            </li>
          ))}
        </ul>
      </div>

      <div style={{ marginBottom: "30px" }}>
        <h2 style={{ marginBottom: "10px" }}>Steps</h2>
        <ol style={{ paddingLeft: "20px" }}>
          {recipe.steps.map((step) => (
            <li key={step.id} style={{ marginBottom: "10px" }}>
              {step.description}
            </li>
          ))}
        </ol>
      </div>

      <div>
        <h2 style={{ marginBottom: "10px" }}>Tags</h2>
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: "10px",
          }}
        >
          {recipe.tags.length > 0 ? (
            recipe.tags.map((tag) => (
              <span
                key={tag.id}
                style={{
                  backgroundColor: "#e0e0e0",
                  borderRadius: "15px",
                  padding: "5px 10px",
                  fontSize: "14px",
                }}
              >
                {tag.name}
              </span>
            ))
          ) : (
            <p>No tags</p>
          )}
        </div>
      </div>
    </div>
  );
}

