import { useEffect, useState } from "react";

interface Recipe {
  id: number;
  name: string;
  description: string;
  prepTime: number;
  cookTime: number;
  tags: string[];
}

interface Tag {
  id: number;
  name: string;
}

export function RecipeListView() {
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [tags, setTags] = useState<Tag[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newRecipe, setNewRecipe] = useState({
    name: "",
    description: "",
    prepTime: "",
    cookTime: "",
    tags: [] as string[],
  });

  useEffect(() => {
    fetchRecipes();
    fetchTags();
  }, []);

  const fetchRecipes = async () => {
    try {
      const response = await fetch("/api/recipes-api/");
      if (!response.ok) throw new Error("Failed to fetch recipes");
      const data = await response.json();
      setRecipes(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const fetchTags = async () => {
    try {
      const response = await fetch("/api/recipes-api/tags");
      if (!response.ok) throw new Error("Failed to fetch tags");
      const data = await response.json();
      setTags(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/recipes-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: newRecipe.name,
          description: newRecipe.description,
          prepTime: parseInt(newRecipe.prepTime),
          cookTime: parseInt(newRecipe.cookTime),
          tags: newRecipe.tags,
        }),
      });

      if (!response.ok) throw new Error("Failed to add recipe");

      // Reset form
      setNewRecipe({
        name: "",
        description: "",
        prepTime: "",
        cookTime: "",
        tags: [],
      });

      // Refresh data
      fetchRecipes();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setNewRecipe({
      ...newRecipe,
      [name]: value,
    });
  };

  const handleTagChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedOptions = Array.from(e.target.selectedOptions, option => option.value);
    setNewRecipe({
      ...newRecipe,
      tags: selectedOptions,
    });
  };

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  const styles = {
    container: {
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
    },
    header: {
      textAlign: "center" as const,
      marginBottom: "20px",
    },
    form: {
      display: "flex" as const,
      flexDirection: "column" as const,
      gap: "10px",
    },
    input: {
      width: "100%",
      padding: "8px",
      borderRadius: "4px",
      border: "1px solid #ccc",
      boxSizing: "border-box" as const,
    },
    timeInput: {
      flex: 1,
      padding: "8px",
      borderRadius: "4px",
      border: "1px solid #ccc",
      boxSizing: "border-box" as const,
    },
    button: {
      padding: "10px 16px",
      backgroundColor: "#007bff",
      color: "white",
      border: "none",
      borderRadius: "4px",
      cursor: "pointer",
    },
    recipeList: {
      marginTop: "20px",
    },
    recipeCard: {
      border: "1px solid #ddd",
      borderRadius: "8px",
      padding: "16px",
      marginBottom: "10px",
    },
    noRecipes: {
      textAlign: "center" as const,
      fontStyle: "italic" as const,
      color: "#666",
    },
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.header}>Recipe Box</h1>

      <form onSubmit={handleSubmit} style={styles.form}>
        <input
          type="text"
          name="name"
          placeholder="Recipe Name"
          value={newRecipe.name}
          onChange={handleInputChange}
          style={styles.input}
        />
        <textarea
          name="description"
          placeholder="Description"
          value={newRecipe.description}
          onChange={handleInputChange}
          style={styles.input}
        />
        <div style={{ display: "flex", gap: "10px" }}>
          <input
            type="number"
            name="prepTime"
            placeholder="Prep Time (min)"
            value={newRecipe.prepTime}
            onChange={handleInputChange}
            style={styles.timeInput}
          />
          <input
            type="number"
            name="cookTime"
            placeholder="Cook Time (min)"
            value={newRecipe.cookTime}
            onChange={handleInputChange}
            style={styles.timeInput}
          />
        </div>
        <select
          multiple
          name="tags"
          onChange={handleTagChange}
          style={styles.input}
        >
          {tags.map(tag => (
            <option key={tag.id} value={tag.name}>
              {tag.name}
            </option>
          ))}
        </select>
        <button type="submit" style={styles.button}>Add Recipe</button>
      </form>

      <div style={styles.recipeList}>
        {recipes.length === 0 ? (
          <p style={styles.noRecipes}>No recipes found. Add your first recipe above!</p>
        ) : (
          recipes.map(recipe => (
            <div key={recipe.id} style={styles.recipeCard}>
              <h3>{recipe.name}</h3>
              <p>{recipe.description}</p>
              <p>Prep Time: {recipe.prepTime} min</p>
              <p>Cook Time: {recipe.cookTime} min</p>
              <p>Tags: {recipe.tags.join(", ")}</p>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

