import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/wine_cellar.db"
);

interface Wine {
  id: number;
  name: string;
  vintage: number;
  drinkBy: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS wines (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    vintage INTEGER NOT NULL,
    drinkBy TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllWines(): Wine[] {
  const stmt = db.prepare(`SELECT * FROM wines`);
  return stmt.all() as unknown as Wine[];
}

export function getWineById(id: number): Wine | undefined {
  const stmt = db.prepare(`SELECT * FROM wines WHERE id = ?`);
  return stmt.get(id) as unknown as Wine | undefined;
}

export function insertWine(wine: Omit<Wine, "id">): number {
  const stmt = db.prepare(
    `INSERT INTO wines (name, vintage, drinkBy) VALUES (?, ?, ?)`
  );
  const result = stmt.run(wine.name, wine.vintage, wine.drinkBy);
  return Number(result.lastInsertRowid);
}

export function updateWine(
  id: number,
  wine: Partial<Omit<Wine, "id">>
): number {
  const updates = [];
  const values: (string | number)[] = [];

  if (wine.name !== undefined) {
    updates.push("name = ?");
    values.push(wine.name);
  }

  if (wine.vintage !== undefined) {
    updates.push("vintage = ?");
    values.push(wine.vintage);
  }

  if (wine.drinkBy !== undefined) {
    updates.push("drinkBy = ?");
    values.push(wine.drinkBy);
  }

  if (updates.length === 0) {
    return 0;
  }

  values.push(id);

  const sql = `UPDATE wines SET ${updates.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  const result = stmt.run(...values);
  return Number(result.changes);
}

export function deleteWine(id: number): number {
  const stmt = db.prepare(`DELETE FROM wines WHERE id = ?`);
  const result = stmt.run(id);
  return Number(result.changes);
}

