export function WineCatalog() {
  const [wines, setWines] = useState<Wine[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newWine, setNewWine] = useState({
    name: "",
    vintage: "",
    region: "",
    grapeVarieties: ""
  });

  useEffect(() => {
    fetchWines();
  }, []);

  const fetchWines = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/wines-api/");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setWines(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/wines-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: newWine.name,
          vintage: parseInt(newWine.vintage),
          region: newWine.region,
          grapeVarieties: newWine.grapeVarieties.split(",").map(g => g.trim())
        })
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      setNewWine({
        name: "",
        vintage: "",
        region: "",
        grapeVarieties: ""
      });
      fetchWines();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/wines-api/${id}`, {
        method: "DELETE"
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
