  name: string;
  drinkByDate: string;
}

export function DrinkByDashboard() {
  const [wines, setWines] = useState<Wine[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchWines();
  }, []);

  const fetchWines = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/wines-api/");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setWines(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString: string) => {
    const options: Intl.DateTimeFormatOptions = { 
      year: "numeric", 
      month: "long", 
      day: "numeric" 
    };
    return new Date(dateString).toLocaleDateString(undefined, options);
  };

  const getDaysUntil = (dateString: string) => {
    const today = new Date();
    const drinkBy = new Date(dateString);
    const diffTime = drinkBy.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays;
  };

  const isOverdue = (dateString: string) => {
    return getDaysUntil(dateString) < 0;
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  if (wines.length === 0) return <div style={{ textAlign: "center", padding: "20px" }}>No wines found.</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Upcoming Drink-By Dates</h1>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
        {wines.map((wine) => {
          const daysUntil = getDaysUntil(wine.drinkByDate);
          const isPastDue = isOverdue(wine.drinkByDate);

          return (
            <div 
              key={wine.id} 
              style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                width: "100%", 
                maxWidth: "300px",
                backgroundColor: isPastDue ? "#ffebee" : "#f5f5f5"
              }}
            >
              <h2 style={{ margin: "0 0 10px 0", fontSize: "1.2em" }}>{wine.name}</h2>
              <p style={{ margin: "5px 0" }}>
                <strong>Drink By:</strong> {formatDate(wine.drinkByDate)}
              </p>
              <p style={{ margin: "5px 0" }}>
                <strong>Days Remaining:</strong> {isPastDue ? "Overdue" : daysUntil}
              </p>
            </div>
          );
        })}
      </div>
    </div>
  );
}

