export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check DELETE requests to the contracts API
  if (req.method !== "DELETE" || !req.path.startsWith("/api/contracts/")) {
    next();
    return;
  }

  // For demonstration purposes, we'll just pass through
