import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("camp-registration.db");

interface Registration {
  id: number;
  childId: number;
  sessionDate: string;
  parentContact: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS registrations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    childId INTEGER NOT NULL,
    sessionDate TEXT NOT NULL,
    parentContact TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllRegistrations(): Registration[] {
  const stmt = db.prepare("SELECT * FROM registrations");
  return stmt.all() as unknown as Registration[];
}

export function getRegistrationById(id: number): Registration | undefined {
  const stmt = db.prepare("SELECT * FROM registrations WHERE id = ?");
  return stmt.get(id) as unknown as Registration | undefined;
}

export function insertRegistration(
  childId: number,
  sessionDate: string,
  parentContact: string
): number {
  const stmt = db.prepare(
    "INSERT INTO registrations (childId, sessionDate, parentContact) VALUES (?, ?, ?)"
  );
  const result = stmt.run(childId, sessionDate, parentContact);
  return Number(result.lastInsertRowid);
}

export function updateRegistration(
  id: number,
  childId: number,
  sessionDate: string,
  parentContact: string
): void {
  const stmt = db.prepare(
    "UPDATE registrations SET childId = ?, sessionDate = ?, parentContact = ? WHERE id = ?"
  );
  stmt.run(childId, sessionDate, parentContact, id);
}

export function deleteRegistration(id: number): void {
  const stmt = db.prepare("DELETE FROM registrations WHERE id = ?");
  stmt.run(id);
}

