    if (!childId || !sessionDate || !parentContact) {
      return res.status(400).json({
        error: "Child ID, session date, and parent contact are required"
      });
    }

    const id = insertRegistration(childId, sessionDate, parentContact);
    const newRegistration = getRegistrationById(id);

    if (!newRegistration) {
      return res.status(500).json({ error: "Failed to create registration" });
    }

    res.status(201).json(newRegistration);
  } catch (error) {
    res.status(500).json({ error: "Failed to create registration" });
  }
});

