import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check DELETE requests
  if (req.method !== "DELETE") {
    next();
    return;
  }

  // Check if the request is for a camp-related resource
  if (!req.path.startsWith("/camps/")) {
    next();
    return;
  }

  // Get the authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify properly
  try {
    // For this implementation, we'll just check if it has the right format
    // In a real system, you'd decode the JWT and verify its signature
    const payload = JSON.parse(atob(token.split(".")[1] || ""));

    // Check if user has supervisor role
    if (payload.role !== "supervisor") {
      res.status(403).json({ error: "Forbidden: Supervisor role required" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

