    return;
  }

  // Get the authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify properly
  // For this implementation, we'll just check if it has the right format
  try {
    // This is a simplified check - in reality, you'd want to verify the JWT signature
    // but since we're not doing full JWT verification, we'll just ensure it's not empty
    if (!token || token.trim() === "") {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // In a real implementation, you'd decode the token and check if user is supervisor
    // For now, we'll assume the token contains a role claim
    // This is a placeholder - actual JWT verification would be more complex

    // Mock supervisor check - in a real app, this would parse the JWT and verify role
