import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

const createTableSql = `
  CREATE TABLE IF NOT EXISTS shifts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    claimed_member_id INTEGER,
    supervisor BOOLEAN
  )
`;

db.exec(createTableSql);

export interface ShiftRow {
  id: number;
  claimed_member_id: number | null;
  supervisor: boolean;
}

export function getAllShifts(): ShiftRow[] {
  const stmt = db.prepare(`SELECT * FROM shifts`);
  return stmt.all() as unknown as ShiftRow[];
}

export function getShiftById(id: number): ShiftRow | undefined {
  const stmt = db.prepare(`SELECT * FROM shifts WHERE id = ?`);
  return stmt.get(id) as unknown as ShiftRow | undefined;
}

export function insertShift(claimedMemberId: number | null, supervisor: boolean): number {
  const stmt = db.prepare(
    `INSERT INTO shifts (claimed_member_id, supervisor) VALUES (?, ?)`
  );
  const result = stmt.run(claimedMemberId, supervisor);
  return Number(result.lastInsertRowid);
}

export function updateShift(id: number, claimedMemberId: number | null, supervisor: boolean): void {
  const stmt = db.prepare(
    `UPDATE shifts SET claimed_member_id = ?, supervisor = ? WHERE id = ?`
  );
  stmt.run(claimedMemberId, supervisor, id);
}

export function deleteShift(id: number): void {
  const stmt = db.prepare(`DELETE FROM shifts WHERE id = ?`);
  stmt.run(id);
}

