import { Router, type Request, type Response } from "express";
import { db, deleteShift, getAllShifts, getShiftById, insertShift, updateShift } from "../db/shifts-table";

export const router = Router();

// Get all shifts
router.get("/", (req: Request, res: Response) => {
  try {
    const shifts = getAllShifts();
    res.json(shifts);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch shifts" });
  }
});

// Get a specific shift by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid shift ID" });
    }

    const shift = getShiftById(id);
    if (!shift) {
      return res.status(404).json({ error: "Shift not found" });
    }

    res.json(shift);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch shift" });
  }
});

// Create a new shift
router.post("/", (req: Request, res: Response) => {
  try {
    const { claimedMemberId, supervisor } = req.body;

    if (claimedMemberId !== null && typeof claimedMemberId !== "number") {
      return res.status(400).json({ error: "claimedMemberId must be a number or null" });
    }

    if (typeof supervisor !== "boolean") {
      return res.status(400).json({ error: "supervisor must be a boolean" });
    }

    const newId = insertShift(claimedMemberId, supervisor);
    const newShift = getShiftById(newId);

    if (!newShift) {
      return res.status(500).json({ error: "Failed to create shift" });
    }

    res.status(201).json(newShift);
  } catch (error) {
    res.status(500).json({ error: "Failed to create shift" });
  }
});

// Update a shift
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid shift ID" });
    }

    const { claimedMemberId, supervisor } = req.body;

    if (claimedMemberId !== null && typeof claimedMemberId !== "number") {
      return res.status(400).json({ error: "claimedMemberId must be a number or null" });
    }

    if (typeof supervisor !== "boolean") {
      return res.status(400).json({ error: "supervisor must be a boolean" });
    }

    const existingShift = getShiftById(id);
    if (!existingShift) {
      return res.status(404).json({ error: "Shift not found" });
    }

    updateShift(id, claimedMemberId, supervisor);
    const updatedShift = getShiftById(id);

    if (!updatedShift) {
      return res.status(500).json({ error: "Failed to update shift" });
    }

    res.json(updatedShift);
  } catch (error) {
    res.status(500).json({ error: "Failed to update shift" });
  }
});

// Delete a shift (supervisor-only)
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid shift ID" });
    }

    const shift = getShiftById(id);
    if (!shift) {
      return res.status(404).json({ error: "Shift not found" });
    }

    // In a real app, we'd check if the user is a supervisor here
    // For now, we'll just allow deletion but enforce the constraint in the DB layer
    deleteShift(id);

    res.json({ message: "Shift deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete shift" });
  }
});

