import { Router, type Request, type Response } from "express";
import {
  db,
  deleteAppointment,
  getAllAppointments,
  getAppointmentById,
  insertAppointment,
  updateAppointment
} from "../db/appointments-table";

export const router = Router();

// Get all appointments
router.get("/", (req: Request, res: Response) => {
  try {
    const appointments = getAllAppointments();
    res.json(appointments);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch appointments" });
  }
});

// Get appointment by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid appointment ID" });
    }

    const appointment = getAppointmentById(id);
    if (!appointment) {
      return res.status(404).json({ error: "Appointment not found" });
    }

    res.json(appointment);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch appointment" });
  }
});

// Create new appointment
router.post("/", (req: Request, res: Response) => {
  try {
    const { patientId, doctorId, timeSlot } = req.body;

    if (!patientId || !doctorId || !timeSlot) {
      return res.status(400).json({ error: "Missing required fields: patientId, doctorId, timeSlot" });
    }

    const id = insertAppointment(patientId, doctorId, timeSlot);
    const newAppointment = getAppointmentById(id);

    if (!newAppointment) {
      return res.status(500).json({ error: "Failed to create appointment" });
    }

    res.status(201).json(newAppointment);
  } catch (error) {
    res.status(500).json({ error: "Failed to create appointment" });
  }
});

// Update appointment
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid appointment ID" });
    }

    const { patientId, doctorId, timeSlot } = req.body;

    if (!patientId || !doctorId || !timeSlot) {
      return res.status(400).json({ error: "Missing required fields: patientId, doctorId, timeSlot" });
    }

    const existingAppointment = getAppointmentById(id);
    if (!existingAppointment) {
      return res.status(404).json({ error: "Appointment not found" });
    }

    updateAppointment(id, patientId, doctorId, timeSlot);
    const updatedAppointment = getAppointmentById(id);

    if (!updatedAppointment) {
      return res.status(500).json({ error: "Failed to update appointment" });
    }

    res.json(updatedAppointment);
  } catch (error) {
    res.status(500).json({ error: "Failed to update appointment" });
  }
});

// Delete appointment
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid appointment ID" });
    }

    const existingAppointment = getAppointmentById(id);
    if (!existingAppointment) {
      return res.status(404).json({ error: "Appointment not found" });
    }

    deleteAppointment(id);
    res.json({ message: "Appointment deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete appointment" });
  }
});

import { Router, type Request, type Response } from "express";
import { db, deleteAppointment, getAllAppointments, getAppointmentById, insertAppointment, updateAppointment } from "../db/appointments-table";

export const router = Router();

// Middleware to check if user is supervisor
const supervisorGuard = (req: Request, res: Response, next: Function) => {
  // For this example, we'll assume a supervisor is identified by a specific header or session
  // In a real application, you'd check actual authentication/authorization logic here
  const isSupervisor = req.headers['x-user-role'] === 'supervisor';

  if (!isSupervisor) {
    return res.status(403).json({ error: 'Access denied: supervisor role required' });
  }

  next();
};

// DELETE route with supervisor guard
router.delete('/appointments/:id', supervisorGuard, (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid appointment ID' });
  }

  const appointment = getAppointmentById(id);

  if (!appointment) {
    return res.status(404).json({ error: 'Appointment not found' });
  }

  deleteAppointment(id);

  return res.json({ message: 'Appointment deleted successfully' });
});

import type { Request, Response, NextFunction } from "express";
import { router as appointmentsRouter } from "../routes/appointments-api";
import { router as supervisorGuardRouter } from "../routes/supervisor-guard";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply guard to DELETE requests to appointment routes
  const isAppointmentDelete = 
    req.method === "DELETE" && 
    (req.path.startsWith("/appointments/") ||
     req.path.startsWith("/api/appointments/"));

  if (!isAppointmentDelete) {
    next();
    return;
  }

  // Check if user is supervisor
  // This is a simplified check - in reality, you'd verify a JWT token
  // and extract role information from it
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (userRole === "supervisor") {
    next();
  } else {
    res.status(403).json({ error: "Forbidden: Supervisor access required" });
  }
}

import { useEffect, useState } from "react";

interface Doctor {
  id: number;
  name: string;
  specialty: string;
}

interface TimeSlot {
  id: number;
  date: string;
  time: string;
  doctorId: number;
}

interface Appointment {
  id: number;
  date: string;
  time: string;
  doctorId: number;
  patientName: string;
}

export function AppointmentBookingView() {
  const [doctors, setDoctors] = useState<Doctor[]>([]);
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [selectedDoctorId, setSelectedDoctorId] = useState<number | null>(null);
  const [selectedTimeSlotId, setSelectedTimeSlotId] = useState<number | null>(null);
  const [patientName, setPatientName] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [appointments, setAppointments] = useState<Appointment[]>([]);

  useEffect(() => {
    fetchDoctors();
    fetchAppointments();
  }, []);

  const fetchDoctors = async () => {
    try {
      const response = await fetch('/api/appointments-api/');
      if (!response.ok) throw new Error('Failed to fetch doctors');
      const data = await response.json();
      setDoctors(data);
    } catch (err) {
      setError('Error loading doctors');
    } finally {
      setLoading(false);
    }
  };

  const fetchTimeSlots = async (doctorId: number) => {
    try {
      const response = await fetch(`/api/appointments-api/${doctorId}`);
      if (!response.ok) throw new Error('Failed to fetch time slots');
      const data = await response.json();
      setTimeSlots(data);
    } catch (err) {
      setError('Error loading time slots');
    }
  };

  const fetchAppointments = async () => {
    try {
      const response = await fetch('/api/appointments-api/');
      if (!response.ok) throw new Error('Failed to fetch appointments');
      const data = await response.json();
      setAppointments(data);
    } catch (err) {
      setError('Error loading appointments');
    }
  };

  const handleDoctorSelect = (doctorId: number) => {
    setSelectedDoctorId(doctorId);
    fetchTimeSlots(doctorId);
    setSelectedTimeSlotId(null);
  };

  const handleTimeSlotSelect = (timeSlotId: number) => {
    setSelectedTimeSlotId(timeSlotId);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedDoctorId || !selectedTimeSlotId || !patientName) return;

    try {
      const response = await fetch('/api/appointments-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          doctorId: selectedDoctorId,
          timeSlotId: selectedTimeSlotId,
          patientName
        })
      });

      if (!response.ok) throw new Error('Failed to book appointment');

      // Reset form
      setSelectedDoctorId(null);
      setSelectedTimeSlotId(null);
      setPatientName("");
      setTimeSlots([]);
      fetchAppointments();
    } catch (err) {
      setError('Error booking appointment');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  return (
    <div style={{
      maxWidth: '600px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <h1 style={{ textAlign: 'center' }}>Book an Appointment</h1>

      {error && <p style={{ color: 'red', textAlign: 'center' }}>{error}</p>}

      <form onSubmit={handleSubmit} style={{ marginBottom: '30px' }}>
        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="patientName" style={{ display: 'block', marginBottom: '5px' }}>
            Your Name
          </label>
          <input
            id="patientName"
            type="text"
            value={patientName}
            onChange={(e) => setPatientName(e.target.value)}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>
            Select Doctor
          </label>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
            {doctors.map(doctor => (
              <button
                key={doctor.id}
                type="button"
                onClick={() => handleDoctorSelect(doctor.id)}
                style={{
                  padding: '10px 15px',
                  borderRadius: '8px',
                  border: '1px solid #ccc',
                  backgroundColor: selectedDoctorId === doctor.id ? '#007bff' : '#fff',
                  color: selectedDoctorId === doctor.id ? '#fff' : '#000',
                  cursor: 'pointer'
                }}
              >
                {doctor.name}
              </button>
            ))}
          </div>
        </div>

        {selectedDoctorId && (
          <div style={{ marginBottom: '15px' }}>
            <label style={{ display: 'block', marginBottom: '5px' }}>
              Available Time Slots
            </label>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
              {timeSlots.length > 0 ? (
                timeSlots.map(slot => (
                  <button
                    key={slot.id}
                    type="button"
                    onClick={() => handleTimeSlotSelect(slot.id)}
                    style={{
                      padding: '10px 15px',
                      borderRadius: '8px',
                      border: '1px solid #ccc',
                      backgroundColor: selectedTimeSlotId === slot.id ? '#28a745' : '#fff',
                      color: selectedTimeSlotId === slot.id ? '#fff' : '#000',
                      cursor: 'pointer'
