import { FC, useEffect, useState } from "react";

interface AdminDeleteGuardProps {
  appointmentId: string;
}

export function AdminDeleteGuard({ appointmentId }: AdminDeleteGuardProps) {
  const [isSupervisor, setIsSupervisor] = useState<boolean | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchSupervisorStatus = async () => {
      try {
        const response = await fetch(`/api/supervisor-guard/appointments/${appointmentId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch supervisor status: ${response.status} ${response.statusText}`);
        }
        const data = await response.json();
        setIsSupervisor(data.isSupervisor);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    if (appointmentId) {
      fetchSupervisorStatus();
    }
  }, [appointmentId]);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (isSupervisor === null) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Unable to determine supervisor status.</div>;
  }

  if (!isSupervisor) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Access denied: This is not a supervisor record.</div>;
  }

  // If we reach here, the user is authorized to proceed with deletion
  return <div style={{ textAlign: "center", padding: "20px" }}>Supervisor record - deletion allowed.</div>;
}

