import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./bike-share-fleet.db");

interface Record {
  id: number;
  bike_id: number;
  mechanic_id: number;
  description: string;
  status: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS records (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    bike_id INTEGER NOT NULL,
    mechanic_id INTEGER NOT NULL,
    description TEXT NOT NULL,
    status TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllRecords(): Record[] {
  const stmt = db.prepare("SELECT * FROM records");
  return stmt.all() as unknown as Record[];
}

export function getRecordById(id: number): Record | undefined {
  const stmt = db.prepare("SELECT * FROM records WHERE id = ?");
  return stmt.get(id) as Record | undefined;
}

export function insertRecord(
  bikeId: number,
  mechanicId: number,
  description: string,
  status: string
): number {
  const stmt = db.prepare(
    "INSERT INTO records (bike_id, mechanic_id, description, status) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(bikeId, mechanicId, description, status);
  return Number(result.lastInsertRowid);
}

export function updateRecord(
  id: number,
  bikeId: number,
  mechanicId: number,
  description: string,
  status: string
): void {
  const stmt = db.prepare(
    "UPDATE records SET bike_id = ?, mechanic_id = ?, description = ?, status = ? WHERE id = ?"
  );
  stmt.run(bikeId, mechanicId, description, status, id);
}

export function deleteRecord(id: number): void {
  const stmt = db.prepare("DELETE FROM records WHERE id = ?");
  stmt.run(id);
}

