import { Router, type Request, type Response } from "express";
import {
  db,
  deleteRecord,
  getAllRecords,
  getRecordById,
  insertRecord,
  updateRecord
} from "../db/records-table";

export const router = Router();

// Get all maintenance records
router.get("/", (req: Request, res: Response) => {
  try {
    const records = getAllRecords();
    return res.json(records);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch records" });
  }
});

// Get a specific maintenance record by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid record ID" });
    }

    const record = getRecordById(id);
    if (!record) {
      return res.status(404).json({ error: "Record not found" });
    }

    return res.json(record);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch record" });
  }
});

// Create a new maintenance record
router.post("/", (req: Request, res: Response) => {
  try {
    const { bikeId, mechanicId, description, status } = req.body;

    if (!bikeId || !mechanicId || !description || !status) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const newId = insertRecord(
      Number(bikeId),
      Number(mechanicId),
      description,
      status
    );

    const newRecord = getRecordById(newId);
    return res.status(201).json(newRecord);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create record" });
  }
});

// Update an existing maintenance record
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid record ID" });
    }

    const { bikeId, mechanicId, description, status } = req.body;

    if (!bikeId || !mechanicId || !description || !status) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const existingRecord = getRecordById(id);
    if (!existingRecord) {
      return res.status(404).json({ error: "Record not found" });
    }

    updateRecord(
      id,
      Number(bikeId),
      Number(mechanicId),
      description,
      status
    );

    const updatedRecord = getRecordById(id);
    return res.json(updatedRecord);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update record" });
  }
});

// Delete a maintenance record
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid record ID" });
    }

    const existingRecord = getRecordById(id);
    if (!existingRecord) {
      return res.status(404).json({ error: "Record not found" });
    }

    deleteRecord(id);
    return res.json({ message: "Record deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete record" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { router as maintenanceRecordsRouter } from "../routes/maintenance-records-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check DELETE requests to the maintenance records API
  if (req.method !== "DELETE" || !req.path.startsWith("/api/maintenance")) {
    next();
    return;
  }

  // For demonstration purposes, we'll assume a role check
  // In a real implementation, this would check the user's role from a token or session
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (userRole !== "supervisor") {
    res.status(403).json({ error: "Forbidden: Delete access requires supervisor role" });
    return;
  }

  next();
}

