export function ShiftSignupForm() {
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedShiftId, setSelectedShiftId] = useState<number | null>(null);
  const [parentName, setParentName] = useState("");

  useEffect(() => {
    fetchShifts();
  }, []);

  const fetchShifts = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/shifts-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch shifts: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setShifts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSignup = async (shiftId: number) => {
    if (!parentName.trim()) {
      alert('Please enter your name');
      return;
    }

    try {
      const response = await fetch(`/api/shifts-api/${shiftId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ caregiver: parentName }),
      });

      if (!response.ok) {
        throw new Error(`Failed to sign up: ${response.status} ${response.statusText}`);
      }

      // Refresh the shifts list
      await fetchShifts();
      setSelectedShiftId(null);
      setParentName("");
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Childcare Shift Signup</h1>

      {shifts.length === 0 ? (
        <p style={{ textAlign: 'center' }}>No shifts available.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {shifts.map(shift => (
            <div key={shift.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <strong>{new Date(shift.date).toLocaleDateString()}</strong>
                  <br />
                  {shift.startTime} - {shift.endTime}
                </div>
                <div>
                  {shift.caregiver ? (
                    <span>Assigned to: {shift.caregiver}</span>
                  ) : (
                    <button 
                      onClick={() => setSelectedShiftId(shift.id)}
                      style={{ backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', padding: '5px 10px' }}
                    >
                      Sign Up
                    </button>
                  )}
                </div>
              </div>

              {selectedShiftId === shift.id && (
                <div style={{ marginTop: '10px', paddingTop: '10px', borderTop: '1px solid #eee' }}>
                  <input
                    type="text"
                    placeholder="Your Name"
                    value={parentName}
                    onChange={(e) => setParentName(e.target.value)}
                    style={{ width: '100%', padding: '8px', marginBottom: '10px', borderRadius: '4px', border: '1px solid #ccc' }}
                  />
                  <div style={{ display: 'flex', gap: '10px' }}>
                    <button 
                      onClick={() => handleSignup(shift.id)}
                      style={{ backgroundColor: '#28a745', color: 'white', border: 'none', borderRadius: '4px', padding: '5px 10px' }}
                    >
                      Confirm Signup
                    </button>
                    <button 
                      onClick={() => setSelectedShiftId(null)}
                      style={{ backgroundColor: '#6c757d', color: 'white', border: 'none', borderRadius: '4px', padding: '5px 10px' }}
                    >
                      Cancel
                    </button>
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

