router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { style, size, current_count } = req.body;

  if (!style || size === undefined || current_count === undefined) {
    return res.status(400).json({ error: "Style, size, and current_count are required" });
  }

  const existingKeg = getKegById(id);

  if (!existingKeg) {
    return res.status(404).json({ error: "Keg not found" });
  }

  updateKeg(id, style, size, current_count);
  const updatedKeg = getKegById(id);

  if (!updatedKeg) {
    return res.status(500).json({ error: "Failed to retrieve updated keg" });
  }

  res.json(updatedKeg);
});

