  const id = Number(req.params.id);

  const existingKeg = getKegById(id);

  if (!existingKeg) {
    return res.status(404).json({ error: "Keg not found" });
  }

  // Supervisor deletion guard - prevent deletion of kegs with current_count > 0
  if (existingKeg.current_count > 0) {
    return res.status(400).json({ error: "Cannot delete keg with remaining beer" });
  }

  deleteKeg(id);

  res.json({ message: "Keg deleted successfully" });
});

