      <h1 style={{ textAlign: "center" }}>Inventory Records</h1>
      <div style={{ marginBottom: "20px", color: "#666" }}>
        Warning: Deleting a record cannot be undone.
      </div>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "10px",
        }}
      >
        {records.map((record) => (
