import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle DELETE requests to /reports/
  if (req.method !== "DELETE" || !req.path.startsWith("/reports/")) {
    next();
    return;
  }

  // Check if user is supervisor
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (in a real app, you'd want proper JWT verification)
  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, "base64url"),
      Buffer.from(expectedSignature, "base64url")
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // For demo purposes, we'll assume the payload contains role info
    // In a real implementation, parse the actual JWT payload
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const userRole = decodedPayload.role;
    const userId = decodedPayload.userId;

    // Get target report ID from URL path
    const reportId = req.path.split("/")[3];

    // In a real app, you'd fetch the report to check who owns it
    // For now, we'll simulate checking ownership
    const isSupervisor = userRole === "supervisor";

    // This is a simplified check - in reality, you'd query the DB
    // to see if the current user is the owner of the report
    const isReportOwner = true; // Placeholder logic

    if (isSupervisor && !isReportOwner) {
      res.status(403).json({ error: "Forbidden: Supervisors can only delete their own reports" });
      return;
    }

    next();
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
  }
}

