import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/cheese-aging-tracker.db"
);

interface AgingBatch {
  id: number;
  cheese_name: string;
  maker_id: number;
  status: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS aging_batches (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    cheese_name TEXT NOT NULL,
    maker_id INTEGER NOT NULL,
    status TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllAgingBatches(): AgingBatch[] {
  const stmt = db.prepare(
    "SELECT * FROM aging_batches ORDER BY id ASC"
  );
  return stmt.all() as unknown as AgingBatch[];
}

export function getAgingBatchById(id: number): AgingBatch | undefined {
  const stmt = db.prepare(
    "SELECT * FROM aging_batches WHERE id = ?"
  );
  return stmt.get(id) as unknown as AgingBatch | undefined;
}

export function insertAgingBatch(
  cheeseName: string,
  makerId: number,
  status: string
): number {
  const stmt = db.prepare(
    "INSERT INTO aging_batches (cheese_name, maker_id, status) VALUES (?, ?, ?)"
  );
  const result = stmt.run(cheeseName, makerId, status);
  return Number(result.lastInsertRowid);
}

export function updateAgingBatch(
  id: number,
  cheeseName: string,
  makerId: number,
  status: string
): void {
  const stmt = db.prepare(
    "UPDATE aging_batches SET cheese_name = ?, maker_id = ?, status = ? WHERE id = ?"
  );
  stmt.run(cheeseName, makerId, status, id);
}

export function deleteAgingBatch(id: number): void {
  const stmt = db.prepare("DELETE FROM aging_batches WHERE id = ?");
  stmt.run(id);
}

