import { Router, type Request, type Response } from "express";
import {
  db,
  deleteAgingBatch,
  getAgingBatchById,
  getAllAgingBatches,
  insertAgingBatch,
  updateAgingBatch
} from "../db/aging-batches-table";

export const router = Router();

// Get all aging batches
router.get("/", (req: Request, res: Response) => {
  const batches = getAllAgingBatches();
  res.json(batches);
});

// Get a specific aging batch by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid batch ID" });
  }

  const batch = getAgingBatchById(id);

  if (!batch) {
    return res.status(404).json({ error: "Batch not found" });
  }

  res.json(batch);
});

// Create a new aging batch
router.post("/", (req: Request, res: Response) => {
  const { cheeseName, makerId, status } = req.body;

  if (!cheeseName || !makerId || !status) {
    return res.status(400).json({ error: "Missing required fields: cheeseName, makerId, status" });
  }

  const newId = insertAgingBatch(cheeseName, makerId, status);

  // Fetch the created batch to send back
  const createdBatch = getAgingBatchById(newId);

  if (!createdBatch) {
    return res.status(500).json({ error: "Failed to retrieve created batch" });
  }

  res.status(201).json(createdBatch);
});

// Update an existing aging batch
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { cheeseName, makerId, status } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid batch ID" });
  }

  if (!cheeseName || !makerId || !status) {
    return res.status(400).json({ error: "Missing required fields: cheeseName, makerId, status" });
  }

  const existingBatch = getAgingBatchById(id);

  if (!existingBatch) {
    return res.status(404).json({ error: "Batch not found" });
  }

  updateAgingBatch(id, cheeseName, makerId, status);

  const updatedBatch = getAgingBatchById(id);

  if (!updatedBatch) {
    return res.status(500).json({ error: "Failed to retrieve updated batch" });
  }

  res.json(updatedBatch);
});

// Delete an aging batch (supervisor-only)
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid batch ID" });
  }

  const existingBatch = getAgingBatchById(id);

  if (!existingBatch) {
    return res.status(404).json({ error: "Batch not found" });
  }

  // In a real application, we would verify supervisor credentials here
  // For now, we'll just proceed with deletion
  deleteAgingBatch(id);

  res.json({ message: "Batch deleted successfully" });
});

