  tool_id: number;
  checkout_timestamp: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS tool_checkouts (
    member_id INTEGER NOT NULL,
    tool_id INTEGER NOT NULL,
    checkout_timestamp TEXT NOT NULL,
    PRIMARY KEY (member_id, tool_id)
  )
`;

db.exec(createTableSql);

export function getAllToolCheckouts(): ToolCheckout[] {
  const stmt = db.prepare(`SELECT * FROM tool_checkouts`);
  return stmt.all() as unknown as ToolCheckout[];
}

export function getToolCheckoutById(
  memberId: number,
  toolId: number
): ToolCheckout | undefined {
  const stmt = db.prepare(
    `SELECT * FROM tool_checkouts WHERE member_id = ? AND tool_id = ?`
  );
  return stmt.get(memberId, toolId) as ToolCheckout | undefined;
}

export function insertToolCheckout(
  memberId: number,
  toolId: number,
  checkoutTimestamp: string
): number {
  const stmt = db.prepare(
    `INSERT INTO tool_checkouts (member_id, tool_id, checkout_timestamp)
     VALUES (?, ?, ?)`
  );
  const result = stmt.run(memberId, toolId, checkoutTimestamp);
  return Number(result.lastInsertRowid);
}

export function updateToolCheckout(
  memberId: number,
  toolId: number,
  checkoutTimestamp: string
): number {
  const stmt = db.prepare(
    `UPDATE tool_checkouts
     SET checkout_timestamp = ?
     WHERE member_id = ? AND tool_id = ?`
  );
  const result = stmt.run(checkoutTimestamp, memberId, toolId);
  return Number(result.changes);
}

export function deleteToolCheckout(
  memberId: number,
  toolId: number
): number {
  const stmt = db.prepare(
    `DELETE FROM tool_checkouts WHERE member_id = ? AND tool_id = ?`
  );
  const result = stmt.run(memberId, toolId);
  return Number(result.changes);
}

