// Get a specific tool checkout by member ID and tool ID
router.get("/:memberId/:toolId", (req: Request, res: Response) => {
  const memberId = Number(req.params.memberId);
  const toolId = Number(req.params.toolId);

  if (isNaN(memberId) || isNaN(toolId)) {
    return res.status(400).json({ error: "Invalid member ID or tool ID" });
  }

  try {
    const checkout = getToolCheckoutById(memberId, toolId);
    if (!checkout) {
      return res.status(404).json({ error: "Tool checkout not found" });
    }
    res.json(checkout);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch tool checkout" });
  }
});

// Create a new tool checkout
router.post("/", (req: Request, res: Response) => {
  const { memberId, toolId, checkoutTimestamp } = req.body;

  if (!memberId || !toolId || !checkoutTimestamp) {
    return res.status(400).json({ error: "Member ID, tool ID, and checkout timestamp are required" });
  }

  try {
    const newId = insertToolCheckout(memberId, toolId, checkoutTimestamp);
    const newCheckout = getToolCheckoutById(memberId, toolId);
    res.status(201).json(newCheckout);
  } catch (error) {
    res.status(500).json({ error: "Failed to create tool checkout" });
  }
});

// Update a tool checkout
router.put("/:memberId/:toolId", (req: Request, res: Response) => {
  const memberId = Number(req.params.memberId);
  const toolId = Number(req.params.toolId);
  const { checkoutTimestamp } = req.body;

  if (isNaN(memberId) || isNaN(toolId)) {
    return res.status(400).json({ error: "Invalid member ID or tool ID" });
  }

  if (!checkoutTimestamp) {
    return res.status(400).json({ error: "Checkout timestamp is required" });
  }

  try {
    const updatedRows = updateToolCheckout(memberId, toolId, checkoutTimestamp);
    if (updatedRows === 0) {
      return res.status(404).json({ error: "Tool checkout not found" });
    }
    const updatedCheckout = getToolCheckoutById(memberId, toolId);
    res.json(updatedCheckout);
  } catch (error) {
    res.status(500).json({ error: "Failed to update tool checkout" });
  }
});

