import { Router, type Request, type Response } from "express";
import { db, deleteTour, getAllTours, getTourById, insertTour, updateTour } from "../db/tours-table";

export const router = Router();

// Get all tours
router.get("/", (req: Request, res: Response) => {
  const tours = getAllTours();
  res.json(tours);
});

// Get a specific tour by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const tour = getTourById(id);

  if (!tour) {
    return res.status(404).json({ error: "Tour not found" });
  }

  res.json(tour);
});

// Create a new tour
router.post("/", (req: Request, res: Response) => {
  const { docentId, exhibitId, date } = req.body;

  if (!docentId || !exhibitId || !date) {
    return res.status(400).json({ error: "Missing required fields: docentId, exhibitId, date" });
  }

  const id = insertTour(docentId, exhibitId, date);
  const newTour = getTourById(id);

  if (!newTour) {
    return res.status(500).json({ error: "Failed to create tour" });
  }

  res.status(201).json(newTour);
});

// Update an existing tour
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { docentId, exhibitId, date } = req.body;

  if (!docentId || !exhibitId || !date) {
    return res.status(400).json({ error: "Missing required fields: docentId, exhibitId, date" });
  }

  const existingTour = getTourById(id);

  if (!existingTour) {
    return res.status(404).json({ error: "Tour not found" });
  }

  updateTour(id, docentId, exhibitId, date);
  const updatedTour = getTourById(id);

  if (!updatedTour) {
    return res.status(500).json({ error: "Failed to update tour" });
  }

  res.json(updatedTour);
});

// Delete a tour
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  const existingTour = getTourById(id);

  if (!existingTour) {
    return res.status(404).json({ error: "Tour not found" });
  }

  deleteTour(id);

  res.json({ message: "Tour deleted successfully" });
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the export endpoint
  if (req.method !== "POST" || req.path !== "/export") {
    next();
    return;
  }

  // Check if the user is the owner
  // This is a placeholder implementation - in a real app,
  // you'd check the authenticated user against the owner
  const isOwner = req.headers["x-user-role"] === "owner";

  if (!isOwner) {
    res.status(403).json({ error: "Access denied. Only owners can export." });
    return;
  }

  next();
}

