import { Router, type Request, type Response } from "express";
import { db, deleteFeeding, getAllFeedings, getFeedingById, insertFeeding, updateFeeding } from "../db/feedings-table";

export const router = Router();

// Get all feedings
router.get("/", (req: Request, res: Response) => {
  try {
    const feedings = getAllFeedings();
    res.json(feedings);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch feedings" });
  }
});

// Get a feeding by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid feeding ID" });
  }

  const feeding = getFeedingById(id);

  if (!feeding) {
    return res.status(404).json({ error: "Feeding not found" });
  }

  res.json(feeding);
});

// Create a new feeding
router.post("/", (req: Request, res: Response) => {
  const { aquariumId, fishSpecies, amountFed, timestamp } = req.body;

  if (!aquariumId || !fishSpecies || !amountFed || !timestamp) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  try {
    const id = insertFeeding(aquariumId, fishSpecies, amountFed, timestamp);
    const newFeeding = getFeedingById(id);

    if (!newFeeding) {
      return res.status(500).json({ error: "Failed to retrieve created feeding" });
    }

    res.status(201).json(newFeeding);
  } catch (error) {
    res.status(500).json({ error: "Failed to create feeding" });
  }
});

// Update a feeding
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { aquariumId, fishSpecies, amountFed, timestamp } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid feeding ID" });
  }

  if (!aquariumId || !fishSpecies || !amountFed || !timestamp) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const existingFeeding = getFeedingById(id);

  if (!existingFeeding) {
    return res.status(404).json({ error: "Feeding not found" });
  }

  try {
    updateFeeding(id, aquariumId, fishSpecies, amountFed, timestamp);
    const updatedFeeding = getFeedingById(id);

    if (!updatedFeeding) {
      return res.status(500).json({ error: "Failed to retrieve updated feeding" });
    }

    res.json(updatedFeeding);
  } catch (error) {
    res.status(500).json({ error: "Failed to update feeding" });
  }
});

// Delete a feeding
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid feeding ID" });
  }

  const existingFeeding = getFeedingById(id);

  if (!existingFeeding) {
    return res.status(404).json({ error: "Feeding not found" });
  }

  try {
    deleteFeeding(id);
    res.json({ message: "Feeding deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete feeding" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { router as feedingsApiRouter } from "../routes/feedings-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check ownership for requests to the feedings API routes
  if (!req.path.startsWith("/api/feedings")) {
    next();
    return;
  }

  // For this example, we'll assume the owner is identified by a fixed ID
  // In a real implementation, this would check the authenticated user
  const ownerID = "owner123";

  // Check if the request has an owner ID in the headers or params
  const requestOwnerID = req.headers["x-owner-id"] as string || req.params.ownerId;

  // If the owner ID doesn't match, reject the request
  if (requestOwnerID !== ownerID) {
    res.status(403).json({ error: "Forbidden: Access denied to this resource." });
    return;
  }

  // If the owner matches, proceed to the next middleware/route handler
  next();
}

