import { Router, type Request, type Response } from "express";
import { insertCheckin, getCheckinById, getAllCheckins, updateCheckin, deleteCheckin } from "../db/checkins-table";
import { getOwnerById } from "../db/owners-table";

export const router = Router();

// POST /check-ins - Record a new check-in
router.post("/check-ins", (req: Request, res: Response) => {
  const { dogId, ownerId, timestamp, cardSerialNumber } = req.body;

  // Validate required fields
  if (!dogId || !ownerId || !timestamp || !cardSerialNumber) {
    return res.status(400).json({ error: "Missing required fields: dogId, ownerId, timestamp, cardSerialNumber" });
  }

  // Validate owner exists
  const owner = getOwnerById(Number(ownerId));
  if (!owner) {
    return res.status(404).json({ error: "Owner not found" });
  }

  // Insert check-in record
  const id = insertCheckin(
    Number(dogId),
    Number(ownerId),
    timestamp,
    cardSerialNumber
  );

  // Return the created check-in
  const newCheckin = getCheckinById(id);
  if (!newCheckin) {
    return res.status(500).json({ error: "Failed to retrieve created check-in" });
  }

