import { Router, type Request, type Response } from "express";
import { getAllCheckins } from "../db/checkins-table";
import { getAllOwners } from "../db/owners-table";

export const router = Router();

router.get("/export", (req: Request, res: Response) => {
  try {
    const checkins = getAllCheckins();
    const owners = getAllOwners();

    // Create CSV header
    let csvContent = "Dog ID,Owner ID,Timestamp,Card Serial Number,Owner Email\r\n";

    // Add each checkin to CSV
    for (const checkin of checkins) {
      const owner = owners.find(o => o.id === checkin.ownerId);
      const ownerEmail = owner ? owner.email : "Unknown";

      csvContent += `${checkin.dogId},${checkin.ownerId},${checkin.timestamp},${checkin.cardSerialNumber},${ownerEmail}\r\n`;
    }

    res.setHeader("Content-Type", "text/csv");
    res.setHeader("Content-Disposition", "attachment; filename=checkins.csv");
    res.status(200).send(csvContent);
  } catch (error) {
    res.status(500).json({ error: "Failed to generate CSV" });
  }
});

