        <button 
          onClick={handleExport}
          style={{
            backgroundColor: '#4CAF50',
            color: 'white',
            border: 'none',
            padding: '10px 15px',
            borderRadius: '4px',
            cursor: 'pointer'
          }}
        >
          Export Data
        </button>
      </div>

      {checkIns.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No check-ins found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {checkIns.map((checkIn) => (
            <div 
              key={checkIn.id} 
              style={{
                border: '1px solid #ccc',
                borderRadius: '8px',
                padding: '15px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center'
              }}
            >
              <div>
                <strong>ID:</strong> {checkIn.id}<br />
                <strong>Name:</strong> {checkIn.name}<br />
                <strong>Time:</strong> {new Date(checkIn.timestamp).toLocaleString()}
              </div>
              <button 
                onClick={() => handleDelete(checkIn.id)}
                style={{
                  backgroundColor: '#f44336',
                  color: 'white',
                  border: 'none',
                  padding: '8px 12px',
                  borderRadius: '4px',
                  cursor: 'pointer'
                }}
