import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./winery-harvest-log.db");

interface HarvestEntry {
  id: number;
  plot_id: number;
  quantity: number;
  owner_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS harvest_entries (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    plot_id INTEGER NOT NULL,
    quantity REAL NOT NULL,
    owner_id INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllHarvestEntries(): HarvestEntry[] {
  const stmt = db.prepare(`SELECT * FROM harvest_entries`);
  return stmt.all() as unknown as HarvestEntry[];
}

export function getHarvestEntryById(id: number): HarvestEntry | undefined {
  const stmt = db.prepare(`SELECT * FROM harvest_entries WHERE id = ?`);
  return stmt.get(id) as unknown as HarvestEntry | undefined;
}

export function insertHarvestEntry(
  plotId: number,
  quantity: number,
  ownerId: number
): number {
  const stmt = db.prepare(
    `INSERT INTO harvest_entries (plot_id, quantity, owner_id) VALUES (?, ?, ?)`
  );
  const result = stmt.run(plotId, quantity, ownerId);
  return Number(result.lastInsertRowid);
}

export function updateHarvestEntry(
  id: number,
  plotId: number,
  quantity: number,
  ownerId: number
): void {
  const stmt = db.prepare(
    `UPDATE harvest_entries SET plot_id = ?, quantity = ?, owner_id = ? WHERE id = ?`
  );
  stmt.run(plotId, quantity, ownerId, id);
}

export function deleteHarvestEntry(id: number): void {
  const stmt = db.prepare(`DELETE FROM harvest_entries WHERE id = ?`);
  stmt.run(id);
}

