import { useEffect, useState } from "react";

export function OwnerOnlyExportPanel() {
  const [isOwner, setIsOwner] = useState<boolean | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Simulate checking if current user is owner
    // In a real app, this would be an API call to verify ownership
    const checkOwnership = async () => {
      try {
        // Mock API call to verify ownership
        // This would normally be something like:
        // const response = await fetch('/api/user/ownership');
        // const data = await response.json();

        // For demo purposes, we'll assume owner status
        // In a real implementation, replace this with actual auth check
        const mockResponse = { isOwner: true };
        setIsOwner(mockResponse.isOwner);
        setLoading(false);
      } catch (err) {
        setError("Failed to verify ownership status.");
        setLoading(false);
      }
    };

    checkOwnership();
  }, []);

  const handleExport = async () => {
    try {
      const response = await fetch('/api/harvest-api/', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }

      const data = await response.json();
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'harvest-log.json';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (err) {
      setError("Failed to export harvest log.");
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (isOwner === false) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Access denied. Only owners can export the harvest log.</div>;
  }

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h2 style={{ textAlign: 'center' }}>Harvest Log Export</h2>
      <p style={{ textAlign: 'center' }}>Download the complete harvest log as a JSON file.</p>
      <div style={{ textAlign: 'center', marginTop: '20px' }}>
        <button 
          onClick={handleExport}
          style={{
            backgroundColor: '#4CAF50',
            color: 'white',
            border: 'none',
            padding: '10px 20px',
            borderRadius: '4px',
            cursor: 'pointer',
            fontSize: '16px'
          }}
        >
          Export Harvest Log
        </button>
      </div>
    </div>
  );
}

