const createTableSql = `
  CREATE TABLE IF NOT EXISTS members (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    farm_id INTEGER NOT NULL,
    subscription_plan TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllMembers(): Member[] {
  const stmt = db.prepare(`SELECT * FROM members`);
  return stmt.all() as unknown as Member[];
}

export function getMemberById(id: number): Member | undefined {
  const stmt = db.prepare(`SELECT * FROM members WHERE id = ?`);
  return stmt.get(id) as unknown as Member | undefined;
}

export function insertMember(farmId: number, subscriptionPlan: string): number {
  const stmt = db.prepare(
    `INSERT INTO members (farm_id, subscription_plan) VALUES (?, ?)`
  );
  const result = stmt.run(farmId, subscriptionPlan);
  return Number(result.lastInsertRowid);
}

export function updateMember(
  id: number,
  farmId: number,
  subscriptionPlan: string
): void {
  const stmt = db.prepare(
    `UPDATE members SET farm_id = ?, subscription_plan = ? WHERE id = ?`
  );
  stmt.run(farmId, subscriptionPlan, id);
}

export function deleteMember(id: number): void {
  const stmt = db.prepare(`DELETE FROM members WHERE id = ?`);
  stmt.run(id);
}

