          </select>
        </div>

        <div style={inputGroupStyle}>
          <label>Items:</label>
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {[
              "Organic Apples",
              "Free Range Eggs",
              "Local Honey",
              "Fresh Vegetables",
              "Artisan Bread",
              "Herbal Tea",
