  return stmt.all() as unknown as GrantRequest[];
}

export function getGrantRequestById(id: number): GrantRequest | undefined {
  const stmt = db.prepare(`SELECT * FROM grant_requests WHERE id = ?`);
  return stmt.get(id) as unknown as GrantRequest | undefined;
}

export function insertGrantRequest(
  applicantId: number,
  amount: number,
  status: string
): number {
  const stmt = db.prepare(
    `INSERT INTO grant_requests (applicant_id, amount, status) VALUES (?, ?, ?)`
  );
  const result = stmt.run(applicantId, amount, status);
  return Number(result.lastInsertRowid);
}

export function updateGrantRequest(
  id: number,
  applicantId: number,
  amount: number,
  status: string
): void {
  const stmt = db.prepare(
    `UPDATE grant_requests SET applicant_id = ?, amount = ?, status = ? WHERE id = ?`
  );
  stmt.run(applicantId, amount, status, id);
}

export function deleteGrantRequest(id: number): void {
  const stmt = db.prepare(`DELETE FROM grant_requests WHERE id = ?`);
  stmt.run(id);
}

