export function GrantRequestForm() {
  const [applicantName, setApplicantName] = useState("");
  const [fundingAmount, setFundingAmount] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError("");

    try {
      const response = await fetch("/api/grant-requests-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          applicantName,
          fundingAmount: Number(fundingAmount),
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to submit grant request: ${response.status}`);
      }

      // Reset form after successful submission
      setApplicantName("");
      setFundingAmount("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      maxWidth: 600,
      margin: "0 auto",
      padding: 20,
    }}>
      <h1 style={{ textAlign: "center" }}>Grant Request Form</h1>

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: 15 }}>
        <div>
          <label htmlFor="applicantName" style={{ display: "block", marginBottom: 5 }}>
            Applicant Name
          </label>
          <input
            id="applicantName"
            type="text"
            value={applicantName}
            onChange={(e) => setApplicantName(e.target.value)}
            style={{ width: "100%", padding: 8, borderRadius: 4, border: "1px solid #ccc" }}
            required
          />
        </div>

        <div>
          <label htmlFor="fundingAmount" style={{ display: "block", marginBottom: 5 }}>
            Funding Amount ($)
          </label>
          <input
            id="fundingAmount"
            type="number"
            value={fundingAmount}
            onChange={(e) => setFundingAmount(e.target.value)}
            style={{ width: "100%", padding: 8, borderRadius: 4, border: "1px solid #ccc" }}
            required
            min="0"
            step="0.01"
          />
        </div>

        <button
          type="submit"
          disabled={loading}
          style={{
            padding: 10,
            backgroundColor: "#007bff",
