      {error && (
        <div style={{
          marginTop: "20px",
          padding: "10px",
          backgroundColor: "#f8d7da",
          borderColor: "#f5c6cb",
          color: "#721c24",
          borderRadius: "4px",
          border: "1px solid",
        }}>
          Error: {error}
        </div>
      )}
    </div>
  );
}

