    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const { kitchenId, date, timeSlot, guestCount } = req.body;

    if (!kitchenId || !date || !timeSlot || !guestCount) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const existingBooking = getBookingById(id);
    if (!existingBooking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    updateBooking(id, kitchenId, date, timeSlot, guestCount);
    const updatedBooking = getBookingById(id);

    if (!updatedBooking) {
      return res.status(500).json({ error: "Failed to update booking" });
    }

    res.json(updatedBooking);
  } catch (error) {
    res.status(500).json({ error: "Failed to update booking" });
  }
});

