import { Router, type Request, type Response } from "express";
import {
  getAllBookings,
  getBookingById,
  insertBooking,
  updateBooking,
  deleteBooking
} from "../db/bookings-table";

export const router = Router();

// Get all bookings
router.get("/", (req: Request, res: Response) => {
  const bookings = getAllBookings();
  res.json(bookings);
});

// Get a booking by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid booking ID" });
  }

  const booking = getBookingById(id);

  if (!booking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  res.json(booking);
});

// Create a new booking
router.post("/", (req: Request, res: Response) => {
  const { memberId, deskId, date } = req.body;

  if (!memberId || !deskId || !date) {
    return res.status(400).json({ error: "Member ID, desk ID, and date are required" });
  }

  const id = insertBooking(memberId, deskId, date);

  res.status(201).json({ id, memberId, deskId, date });
});

// Update a booking
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { memberId, deskId, date } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid booking ID" });
  }

  if (!memberId || !deskId || !date) {
    return res.status(400).json({ error: "Member ID, desk ID, and date are required" });
  }

  const existingBooking = getBookingById(id);

  if (!existingBooking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  updateBooking(id, memberId, deskId, date);

  res.json({ id, memberId, deskId, date });
});

// Delete a booking
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid booking ID" });
  }

  const existingBooking = getBookingById(id);

  if (!existingBooking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  deleteBooking(id);

  res.json({ message: "Booking deleted successfully" });
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check requests to the bookings endpoint
  if (!(req.path.startsWith("/bookings") && req.method === "GET")) {
    next();
    return;
  }

  // Check if the user is a regular member
  // Assuming req.user exists and has a role property
  // This is a simplified check - in reality, you'd want to verify the token signature
  // and extract the user data properly
  const userRole = (req as any).user?.role;

  // If user is not authenticated or is not a member, allow access
  if (!userRole || userRole !== "member") {
    next();
    return;
  }

  // If user is a member, check if they're trying to access another member's bookings
  // Extract the member ID from the URL path
  const pathParts = req.path.split("/");
  const targetMemberId = pathParts[3]; // Assuming the path is /bookings/:memberId

  // Get the current user's ID from the request (assuming it's set by auth middleware)
  const currentUserId = (req as any).user?.id;

  // If there's no target member ID or no current user ID, allow access
  if (!targetMemberId || !currentUserId) {
    next();
    return;
  }

  // If the current user is trying to view another member's bookings, reject
  if (targetMemberId !== currentUserId) {
    res.status(403).json({ error: "Forbidden: You can only view your own bookings." });
    return;
  }

  // If we get here, the user is authorized to view their own bookings
  next();
}

