export function DeskBookingView() {
  const [desks, setDesks] = useState<Desk[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchDesks();
  }, []);

  const fetchDesks = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/bookings-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch desks: ${response.status}`);
      }
      const desksData = await response.json();
      setDesks(desksData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleBookDesk = async (deskId: string) => {
    try {
      const response = await fetch(`/api/bookings-api/${deskId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ isBooked: true }),
      });

      if (!response.ok) {
        throw new Error(`Failed to book desk: ${response.status}`);
      }

      // Refresh the list after booking
      await fetchDesks();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleReleaseDesk = async (deskId: string) => {
    try {
      const response = await fetch(`/api/bookings-api/${deskId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ isBooked: false }),
      });

      if (!response.ok) {
        throw new Error(`Failed to release desk: ${response.status}`);
      }

      // Refresh the list after releasing
      await fetchDesks();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Available Desks</h1>
      {desks.length === 0 ? (
        <p style={{ textAlign: "center", color: "gray" }}>No desks available.</p>
      ) : (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "15px",
          }}
        >
          {desks.map((desk) => (
            <div
              key={desk.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "8px",
                padding: "15px",
                backgroundColor: desk.isBooked ? "#f9f9f9" : "#fff",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <span>{desk.location}</span>
              <div>
                {desk.isBooked ? (
                  <button
                    onClick={() => handleReleaseDesk(desk.id)}
                    style={{
                      backgroundColor: "#ff6b6b",
                      color: "white",
                      border: "none",
                      borderRadius: "4px",
                      padding: "8px 12px",
                      cursor: "pointer",
                    }}
                  >
                    Release
                  </button>
                ) : (
                  <button
                    onClick={() => handleBookDesk(desk.id)}
                    style={{
                      backgroundColor: "#4caf50",
                      color: "white",
                      border: "none",
                      borderRadius: "4px",
                      padding: "8px 12px",
                      cursor: "pointer",
                    }}
                  >
                    Book
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

