import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply to PUT requests to /rooms/:id/status
  if (req.method !== "PUT" || !req.path.match(/^\/rooms\/[^\/]+\/status$/)) {
    next();
    return;
  }

  // Check if the user has access to the specific room
  const roomId = req.params.id;
  const userRoomId = req.body.roomId;

  // If the user is trying to update a room they don't have access to
  if (roomId !== userRoomId) {
    res.status(403).json({ error: "Forbidden" });
    return;
  }

  next();
}

