import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process GET requests to reservation-related endpoints
  if (req.method !== "GET" || !req.path.startsWith("/reservations")) {
    next();
    return;
  }

  // Check if user is authenticated via Authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (in a real system, you'd decode and verify)
  // For this example, we'll assume the token contains user ID
  try {
    // In a real implementation, you would decode the JWT and verify its signature
    // This is a simplified version for demonstration purposes
    const [userId, signature] = token.split(".");

    if (!userId || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", secret)
      .update(userId)
      .digest("hex");

    const signatureBuffer = Buffer.from(signature, "hex");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "hex");

    if (signatureBuffer.length !== expectedSignatureBuffer.length ||
        !timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // Store user ID in request for later use in reservation lookup
    (req as any).userId = userId;
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}

import { useEffect, useState } from "react";

interface Reservation {
