import { useEffect, useState } from "react";

interface Booking {
  id: number;
  memberId: number;
  title: string;
  date: string;
  startTime: string;
  endTime: string;
}

interface User {
  id: number;
  role: "member" | "admin";
}

export function MemberOnlyViewGuard() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchUserData = async () => {
      try {
        const userResponse = await fetch("/api/user");
        if (!userResponse.ok) throw new Error("Failed to fetch user data");
        const userData = await userResponse.json();
        setCurrentUser(userData);

        const bookingsResponse = await fetch("/api/bookings-api/");
        if (!bookingsResponse.ok) throw new Error("Failed to fetch bookings");
        const bookingsData = await bookingsResponse.json();

        if (userData.role === "admin") {
          setBookings(bookingsData);
        } else {
          const filteredBookings = bookingsData.filter(
            (booking: Booking) => booking.memberId === userData.id
          );
          setBookings(filteredBookings);
        }

        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchUserData();
  }, []);

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  if (!currentUser) return <div style={{ textAlign: "center", padding: "20px" }}>No user data available</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>My Bookings</h1>

      {bookings.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No bookings found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {bookings.map(booking => (
            <div key={booking.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
              <h3>{booking.title}</h3>
              <p><strong>Date:</strong> {booking.date}</p>
              <p><strong>Time:</strong> {booking.startTime} - {booking.endTime}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./club-budget.db");

interface Expense {
  id: number;
  memberId: number;
  amount: number;
  description: string;
  approved: boolean;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS expenses (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    memberId INTEGER NOT NULL,
    amount REAL NOT NULL,
    description TEXT NOT NULL,
    approved BOOLEAN NOT NULL DEFAULT FALSE
  );
`;

db.exec(createTableSql);

export function getAllExpenses(): Expense[] {
  const stmt = db.prepare("SELECT * FROM expenses");
  return stmt.all() as unknown as Expense[];
}

export function getExpenseById(id: number): Expense | undefined {
  const stmt = db.prepare("SELECT * FROM expenses WHERE id = ?");
  return stmt.get(id) as unknown as Expense | undefined;
}

export function insertExpense(
  memberId: number,
  amount: number,
  description: string,
  approved: boolean
): number {
  const stmt = db.prepare(
    "INSERT INTO expenses (memberId, amount, description, approved) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(memberId, amount, description, approved);
  return Number(result.lastInsertRowid);
}

export function updateExpense(
  id: number,
  memberId: number,
  amount: number,
  description: string,
  approved: boolean
): void {
  const stmt = db.prepare(
    "UPDATE expenses SET memberId = ?, amount = ?, description = ?, approved = ? WHERE id = ?"
  );
  stmt.run(memberId, amount, description, approved, id);
}

export function deleteExpense(id: number): void {
  const stmt = db.prepare("DELETE FROM expenses WHERE id = ?");
  stmt.run(id);
}

