import { Router, type Request, type Response } from "express";
import {
  db,
  deleteExpense,
  getAllExpenses,
  getExpenseById,
  insertExpense,
  updateExpense
} from "../db/expenses-table";

export const router = Router();

// Get all expenses
router.get("/", (req: Request, res: Response) => {
  try {
    const expenses = getAllExpenses();
    return res.json(expenses);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch expenses" });
  }
});

// Get expense by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid expense ID" });
    }

    const expense = getExpenseById(id);
    if (!expense) {
      return res.status(404).json({ error: "Expense not found" });
    }

    return res.json(expense);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch expense" });
  }
});

// Create new expense
router.post("/", (req: Request, res: Response) => {
  try {
    const { memberId, amount, description, approved } = req.body;

    if (
      typeof memberId !== "number" ||
      typeof amount !== "number" ||
      typeof description !== "string" ||
      typeof approved !== "boolean"
    ) {
      return res.status(400).json({
        error: "Invalid input: memberId, amount, description, and approved are required"
      });
    }

    const id = insertExpense(memberId, amount, description, approved);
    return res.status(201).json({ id });
  } catch (error) {
    return res.status(500).json({ error: "Failed to create expense" });
  }
});

// Update expense
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid expense ID" });
    }

    const { memberId, amount, description, approved } = req.body;

    if (
      typeof memberId !== "number" ||
      typeof amount !== "number" ||
      typeof description !== "string" ||
      typeof approved !== "boolean"
    ) {
      return res.status(400).json({
        error: "Invalid input: memberId, amount, description, and approved are required"
      });
    }

    const existingExpense = getExpenseById(id);
    if (!existingExpense) {
      return res.status(404).json({ error: "Expense not found" });
    }

    updateExpense(id, memberId, amount, description, approved);
    return res.json({ message: "Expense updated successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to update expense" });
  }
});

// Delete expense
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid expense ID" });
    }

    const existingExpense = getExpenseById(id);
    if (!existingExpense) {
      return res.status(404).json({ error: "Expense not found" });
    }

    deleteExpense(id);
    return res.json({ message: "Expense deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete expense" });
  }
});

