import { useEffect, useState } from "react";

interface Rehearsal {
  id: number;
  date: string;
  time: string;
  location: string;
  status: string;
}

export function RehearsalConfirmationPage() {
  const [rehearsals, setRehearsals] = useState<Rehearsal[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchRehearsals();
  }, []);

  const fetchRehearsals = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/rehearsal-api/");
      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }
      const data = await response.json();
      setRehearsals(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleAttendanceChange = async (id: number, attended: boolean) => {
    try {
      const response = await fetch(`/api/rehearsal-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ attended }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }

      // Refresh the list after updating
      await fetchRehearsals();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (rehearsals.length === 0) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No rehearsals scheduled.</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Rehearsal Confirmation</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {rehearsals.map((rehearsal) => (
          <div 
            key={rehearsal.id} 
            style={{ 
              border: "1px solid #ccc", 
              borderRadius: "8px", 
              padding: "15px", 
              display: "flex", 
              justifyContent: "space-between", 
              alignItems: "center"
            }}
          >
            <div>
              <h3>{rehearsal.date} at {rehearsal.time}</h3>
              <p>{rehearsal.location}</p>
              <p>Status: {rehearsal.status}</p>
            </div>
            <div>
              <button 
                onClick={() => handleAttendanceChange(rehearsal.id, true)}
                style={{ 
                  backgroundColor: "#4CAF50", 
                  color: "white", 
                  border: "none", 
                  padding: "10px 15px", 
                  borderRadius: "4px", 
                  cursor: "pointer", 
                  marginRight: "10px"
                }}
              >
                Attended
              </button>
              <button 
                onClick={() => handleAttendanceChange(rehearsal.id, false)}
                style={{ 
                  backgroundColor: "#f44336", 
                  color: "white", 
                  border: "none", 
                  padding: "10px 15px", 
                  borderRadius: "4px", 
                  cursor: "pointer"
                }}
              >
                Did Not Attend
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

