import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply guard to GET requests
  if (req.method !== "GET") {
    next();
    return;
  }

  // Check if the request is for member-specific data
  const path = req.path;
  if (!path.startsWith("/members/")) {
    next();
    return;
  }

  // Extract member ID from path
  const pathParts = path.split("/");
  const requestedMemberId = pathParts[3];

  // Get member ID from token (assuming it's in the Authorization header)
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token verification (in a real app, use proper JWT library)
  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Verify signature
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // Decode payload to get member ID
    const payloadDecoded = Buffer.from(payload, "base64url").toString("utf8");
    const payloadObj = JSON.parse(payloadDecoded);
    const authenticatedMemberId = payloadObj.memberId;

    // Compare member IDs
    if (authenticatedMemberId !== requestedMemberId) {
      res.status(403).json({ error: "Forbidden: Access to member data denied" });
      return;
    }

