import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./routes.db");

interface Route {
  id: number;
  name: string;
  grade: string;
  setterId: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS routes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    grade TEXT NOT NULL,
    setterId INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllRoutes(): Route[] {
  const stmt = db.prepare("SELECT * FROM routes");
  return stmt.all() as unknown as Route[];
}

export function getRouteById(id: number): Route | undefined {
  const stmt = db.prepare("SELECT * FROM routes WHERE id = ?");
  return stmt.get(id) as unknown as Route | undefined;
}

export function insertRoute(name: string, grade: string, setterId: number): number {
  const stmt = db.prepare(
    "INSERT INTO routes (name, grade, setterId) VALUES (?, ?, ?)"
  );
  const result = stmt.run(name, grade, setterId);
  return Number(result.lastInsertRowid);
}

export function updateRoute(id: number, name: string, grade: string, setterId: number): void {
  const stmt = db.prepare(
    "UPDATE routes SET name = ?, grade = ?, setterId = ? WHERE id = ?"
  );
  stmt.run(name, grade, setterId, id);
}

export function deleteRoute(id: number): void {
  const stmt = db.prepare("DELETE FROM routes WHERE id = ?");
  stmt.run(id);
}

